INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (1, 0, "ヒヨリ", "", "vo_empress_100101_001", 5, "vo_empress_100101_001", "", 1, "どんなに敵が大勢でも、みんなで\n力を合わせれば絶対大丈夫だよ！\nだから顔を上げてこう！\nごーごー！", 1, 100101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (2, 0, "ヒヨリ", "", "vo_empress_100101_002", 5, "vo_empress_100101_002", "", 1, "ううっ、何度も戦う相手もいるけど\nあたし、負けたりなんてしないよ！\n今回だってみんなや騎士くんがいる\nフルパワーでいくよーっ！", 1, 100103, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 0, "ヒヨリ", "", "vo_empress_100101_003", 5, "vo_empress_100101_003", "", 1, "うぅ…すごい力…！\n…でも、なんだか悲しそう\nこの人の気持ちを知りたい\nだからこそ…勝たなきゃ…！", 2, 100103, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (4, 100101, "ヒヨリ", "", "vo_empress_100101_004", 5, "vo_empress_100101_004", "", 1, "騎士くんの力があれば、\nあたしは絶対負けないよ！\nみんなが笑顔でいられるように\n一緒にがんばろう！", 3, 100102, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, 0, "ユイ", "", "vo_empress_100201_001", 5, "vo_empress_100201_001", "", 1, "わたしたちの世界のためにも\nこの世界のためにも、\n絶対に負けられない…！\nがんばろうね、騎士クン", 1, 100203, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (6, 0, "ユイ", "", "vo_empress_100201_002", 5, "vo_empress_100201_002", "", 1, "みんな、怪我したらすぐに教えて！\n…もう誰も失いたくないの\nそのために修行もしたんだから…\n大丈夫、絶対なんとかしてみせる！", 1, 100203, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (7, 0, "ユイ", "", "vo_empress_100201_003", 5, "vo_empress_100201_003", "", 1, "世界を『書き換え』するなんて…\nそんな未来、寂しいだけだよ…！\nお願い、これ以上みんなを\n傷つけないで…話を聞いて！", 2, 100203, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (8, 100201, "ユイ", "", "vo_empress_100201_004", 5, "vo_empress_100201_004", "", 1, "感じるよ、騎士クンの気持ち…\n抱きしめられてるみたいに\nあったかい…\nぜんぶ終わらせよう！", 3, 100202, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (9, 0, "レイ", "", "vo_empress_100301_001", 5, "vo_empress_100301_001", "", 1, "厳しい戦いになるだろうな\n安心してくれ、何があっても\nキミは守る。…いや、違うな\n一緒に、世界を守ろう", 1, 100301, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (10, 0, "レイ", "", "vo_empress_100301_002", 5, "vo_empress_100301_002", "", 1, "手ごわい相手ばかりだな…\nだが引き下がるわけにはいかない\nこちらにだって譲れないものが\nあるんだ！", 1, 100303, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (11, 0, "レイ", "", "vo_empress_100301_003", 5, "vo_empress_100301_003", "", 1, "くっ…なんて力だ…！\n防ぐだけで精一杯…だが、\n例え剣が折れたとしても、\n私は最後まで戦い続ける！", 2, 100303, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (12, 100301, "レイ", "", "vo_empress_100301_004", 5, "vo_empress_100301_004", "", 1, "感じるよ、キミからの愛\nこれがあれば、私はどんな\n敵にだって打ち勝てる！\n見せてやろう、一緒に！", 3, 100302, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (13, 0, "ミソギ", "", "vo_empress_100401_001", 5, "vo_empress_100401_001", "", 1, "ミソギとにいちゃんはこれからも\n世界中を冒険して、ワクワクする\nお宝をたくさん見つけるんだ！\nワルモノなんかに邪魔させないよ！", 1, 100401, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (14, 0, "ミソギ", "", "vo_empress_100401_002", 5, "vo_empress_100401_002", "", 1, "わわ、なんかヤバそうな雰囲気…\nこういう時こそミソギの出番だね！\nとっておきのイタズラ決めて、\nピンチもひっくり返しちゃうよ！", 1, 100401, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (15, 0, "ミソギ", "", "vo_empress_100401_003", 5, "vo_empress_100401_003", "", 1, "うぅ…あの悪者、すごい迫力だよ…\nもしミソギたちが負けちゃったら、\nミソギもにいちゃんもこの世界も…\n全部おしまい、なんだよね…？", 2, 100403, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (16, 100401, "ミソギ", "", "vo_empress_100401_004", 5, "vo_empress_100401_004", "", 1, "ミソギたちが世界を救っちゃったら\nきっとみんなびっくりするよね！\nどんな顔して驚いてくれるかな…\nにひひ、なんかワクワクしてきた！", 3, 100402, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (17, 0, "マツリ", "", "vo_empress_100501_001", 5, "vo_empress_100501_001", "", 1, "歴代オールヒーロー大進撃ッス～！\n自分は新世代のエースってとこッス\nかね？　さあ、ついてくるッス……\nあれ？　みんなどこ？　待って～", 1, 100501, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (18, 0, "マツリ", "", "vo_empress_100501_002", 5, "vo_empress_100501_002", "", 1, "敵は圧倒的な力で、こっちを絶望\nさせる気ッスかね？　だとしたら\n大誤算ッスよ！　むしろ自分の\n正義の魂に火をつけたんスから！", 1, 100501, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (19, 0, "マツリ", "", "vo_empress_100501_003", 5, "vo_empress_100501_003", "", 1, "足が……震えるッス……けど！\nこれは武者震いッス……！　だって\nヒーローは絶対に絶対にっ！\n敗北なんてしないんスから……っ！", 2, 100503, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (20, 100501, "マツリ", "", "vo_empress_100501_004", 5, "vo_empress_100501_004", "", 1, "さあ、手と手をつないで、\n二人で教えてやるッスよ！\nどんな物語でも、悪は必ずヒーロー\nに打ち倒されるってことを！", 3, 100502, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (21, 0, "アカリ", "", "vo_empress_100601_001", 5, "vo_empress_100601_001", "", 1, "ひゃぁんっ！\nもう、敵さんが脅かしてくるから\nアカリ、ヘンな声出ちゃいました…\nこういうの、よくないですよっ", 1, 100603, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (22, 0, "アカリ", "", "vo_empress_100601_002", 5, "vo_empress_100601_002", "", 1, "アカリ、お兄ちゃんとシタイコトが\nまだまだいっぱいあるんです！\nだから、私たちの大事な世界も…\n本気で守り抜いてみせますっ！", 1, 100601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (23, 0, "アカリ", "", "vo_empress_100601_003", 5, "vo_empress_100601_003", "", 1, "うぅ…こんなに激しく攻められたら\nアカリ、もう壊れちゃいそうです…\nだけどまだまだ…戦えますっ！\nお兄ちゃんが一緒なんですからっ…", 2, 100603, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (24, 100601, "アカリ", "", "vo_empress_100601_004", 5, "vo_empress_100601_004", "", 1, "お兄ちゃんの愛を注いでもらって\nアカリ超絶パワーアップです！\nアカリらしく世界一かわいく、\n世界を救ってみせちゃいますよ！", 3, 100602, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (25, 0, "ミヤコ", "", "vo_empress_100701_001", 5, "vo_empress_100701_001", "", 1, "アイツらが野放しだと、ミヤコは\n安心してプリンを食べられないの\n今日のプリンと明日のプリンの\nためにも、絶対負けないの！", 1, 100701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (26, 0, "ミヤコ", "", "vo_empress_100701_002", 5, "vo_empress_100701_002", "", 1, "前はミヤコ、悪いヤツに捕まって\n消されそうになって怖かったの…\nでも今度は全然怖くないの！\nオマエが一緒なら平気なの！", 1, 100702, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (27, 0, "ミヤコ", "", "vo_empress_100701_003", 5, "vo_empress_100701_003", "", 1, "むうぅ～っ、アイツしつこいの！\nこうなったら、オマエにも\nミヤコのプリン分けてやるの！\nダブルプリンパワーで頑張るの！", 2, 100703, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (28, 100701, "ミヤコ", "", "vo_empress_100701_004", 5, "vo_empress_100701_004", "", 1, "アイツはどんなに強くたって、\n独りぼっちのさびしいヤツなの\nでもオマエにはミヤコがいるの！\nミヤコたちなら絶対に勝てるの！", 3, 100702, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (29, 0, "ユキ", "", "vo_empress_100801_001", 5, "vo_empress_100801_001", "", 1, "相手が誰であれ、やることは同じ…\nそう…ボクの美しさを見せてあげる\nことさ！　予言しよう…絶世の美の\n前にはどんな敵もひれ伏すと、ね！", 1, 100801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (30, 0, "ユキ", "", "vo_empress_100801_002", 5, "vo_empress_100801_002", "", 1, "少し待っていてくれる？　メイクを\n直さないと。避けられない戦いなら\nせめて美しいボクと戦えることを\n彼らには誇りに思ってほしいからね", 1, 100801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (31, 0, "ユキ", "", "vo_empress_100801_003", 5, "vo_empress_100801_003", "", 1, "どうせ倒れるなら美しいままで散り\nたいな。ふふ、難しい望みかな…？\nそれでもボクは、最後まで美しく\nあがいてみせるよ、キミと一緒にね", 2, 100801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (32, 100801, "ユキ", "", "vo_empress_100801_004", 5, "vo_empress_100801_004", "", 1, "ボクがいて、キミがいる。ボクたち\nが勝つのに、これ以上の理由はない\nよね。だって美しい者が勝つ未来の\nほうが、美しいエンディングだもの", 3, 100802, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (33, 0, "アンナ", "", "vo_empress_100901_001", 5, "vo_empress_100901_001", "", 1, "災厄の嵐が吹き荒れ、世界の命運は\n風前の灯が如く儚い。だが絶望には\nまだ早い！　希望はここに在り！\n灯火を掲げよう、盟友シグルドよ！", 1, 100901, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (34, 0, "アンナ", "", "vo_empress_100901_002", 5, "vo_empress_100901_002", "", 1, "終焉の日、滅びの刻来たれり、か…\nだが、幾度も転生を繰り返しながら\n戦いつづけた我らの宿命を思えば、\nこの程度取るに足らない…はずだ！", 1, 100903, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (35, 0, "アンナ", "", "vo_empress_100901_003", 5, "vo_empress_100901_003", "", 1, "くっ…なんという禍々しい魔力…！\nもはや世界の滅びも間近…しかし\n疾風の冥姫がここで退くわけには\nいかぬ！　しぶとく抗ってみせるぞ", 2, 100903, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (36, 100901, "アンナ", "", "vo_empress_100901_004", 5, "vo_empress_100901_004", "", 1, "永遠の盟約で結ばれし魂の伴侶…\n世界を滅ぼさんとする災禍の剣も\nこの絆を断ち切ることはできない！\n覚悟するがいい、幻境竜后！！", 3, 100902, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (37, 0, "マホ", "", "vo_empress_101001_001", 5, "vo_empress_101001_001", "", 1, "【自警団】のギルドマスターとして\nしゃんとして恥ずかしない姿を\n見せなあきまへんなぁ…王子はん\nしゃなりしゃなり、いきまひょ！", 1, 101001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (38, 0, "マホ", "", "vo_empress_101001_002", 5, "vo_empress_101001_002", "", 1, "王子はん、服が破れてますえ？\nこれでよし…うん、完璧や♪\n戦いの中でも、王子はんには\n格好良う居てもらいたいさかいに♪", 1, 101001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (39, 0, "マホ", "", "vo_empress_101001_003", 5, "vo_empress_101001_003", "", 1, "幻境竜后…大層なお名前してはる\nお后さまが勝負を挑んできはるなら\nうちも、マホマホ王国の姫として…\n正々堂々受けて立ちますえ！", 2, 101003, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (40, 101001, "マホ", "", "vo_empress_101001_004", 5, "vo_empress_101001_004", "", 1, "強い愛で結ばれた王子と姫を\n引き裂くことは誰にもできまへん\n王子はん…ふたりで一緒に！\nハッピーエンドを迎えまひょ！", 3, 101002, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (41, 0, "リノ", "", "vo_empress_101101_001", 5, "vo_empress_101101_001", "", 1, "お兄ちゃんがいれば百人力士っ！\n妹パワーも全開でいきますよ～♪\nどんな敵でもドンドンこいですっ！\nあれ？　ちょっと違いました？", 1, 101101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (42, 0, "リノ", "", "vo_empress_101101_002", 5, "vo_empress_101101_002", "", 1, "これぞまさに『四面そば』…\n敵多すぎでもう大盛りですけど\n秘密結社の一員として、妹として\nこの世界の平和は守り通しますっ！", 1, 101101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (43, 0, "リノ", "", "vo_empress_101101_003", 5, "vo_empress_101101_003", "", 1, "あれが幻境竜后…不思議な服…\nじゃなくて、空気がピリピリです…\nちょっとだけ怖いけど…妹として\n絶対に降参なんてしませんよ！", 2, 101103, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (44, 101101, "リノ", "", "vo_empress_101101_004", 5, "vo_empress_101101_004", "", 1, "私、もう迷いません！\nお兄ちゃんと一緒なら\nどんな敵だって倒しちゃいます！\n妹のポテンシャルは無限大ですよ！", 3, 101102, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (45, 0, "ハツネ", "", "vo_empress_101201_001", 5, "vo_empress_101201_001", "", 1, "どんなに大変な時でもキミと一緒に\nず～っと乗り越えてきたんだもん！\nだからっ、今回もきっと大丈夫！\n私の魔法できらーん☆　だよっ！", 1, 101201, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (46, 0, "ハツネ", "", "vo_empress_101201_002", 5, "vo_empress_101201_002", "", 1, "力を使いすぎると眠く…スヤァ…\nはっ、いけないいけない！\nキミ、私が寝ちゃったら起こして！\n…お、王子様のキスとかで…", 1, 101202, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (47, 0, "ハツネ", "", "vo_empress_101201_003", 5, "vo_empress_101201_003", "", 1, "も～！　容赦なさすぎだよぉ！\nそっ、それにさっきまでの戦いの\nせいで、ね、眠気がぁ～っ…\nハ、ハツネちゃん、ピ～ンチ…", 2, 101203, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (48, 101201, "ハツネ", "", "vo_empress_101201_004", 5, "vo_empress_101201_004", "", 1, "幻境竜后さんがどんなに強くても\n今のハツネちゃんは無敵なのだ～！\n大好きなキミと！　シオリンと！\nみんながいる世界を守っちゃうよ！", 3, 101202, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (49, 0, "ナナカ", "", "vo_empress_101301_001", 5, "vo_empress_101301_001", "", 1, "この世界にはね、たくさんの人の\n『好き』が詰まってるんだよ\nそれをぶち壊すなんて鬼畜の所業\nナナカちゃんが許しはしないぜ！", 1, 101301, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (50, 0, "ナナカ", "", "vo_empress_101301_002", 5, "vo_empress_101301_002", "", 1, "見るからにヤバい奴らが勢ぞろい！\nでもみんなの世界が狙われてんのに\n日和ってる奴いる？いねえよなぁ！\n全員ぶっ飛ばして世界を救うぞ！！", 1, 101301, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (51, 0, "ナナカ", "", "vo_empress_101301_003", 5, "vo_empress_101301_003", "", 1, "あとはラスボスを倒せば勝利ッ！\n第３部完！　…とはいかない感じ？\nていうか逆にピンチな気配？\nどっどうしよう、どうすれば！？", 2, 101303, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (52, 101301, "ナナカ", "", "vo_empress_101301_004", 5, "vo_empress_101301_004", "", 1, "幻境竜后…確かに強敵だったね\nでも今はもう負ける気がしないかな\nだって私は、ただのナナカじゃない\n超ナナカちゃんだから…！", 3, 101302, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (53, 0, "カスミ", "", "vo_empress_101401_001", 5, "vo_empress_101401_001", "", 1, "あちらにもなかなかの陰謀家がいる\nようだね。彼女らの最大の誤算は\nここに希代の名探偵がいることさ！\nさあ助手くん。真実を勝ち取ろう！", 1, 101401, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (54, 0, "カスミ", "", "vo_empress_101401_002", 5, "vo_empress_101401_002", "", 1, "仕方ない、こうなったら奥の手だ\nミスティ！　セオリー！　…って\nこらぁっ！　変身の最中は待って\nくれるのがお約束だよ！？", 1, 101401, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (55, 0, "カスミ", "", "vo_empress_101401_003", 5, "vo_empress_101401_003", "", 1, "なっ…なんだい、この悪寒は…\n触れてはならない何か…いいや！\n名探偵たるもの巨悪に恐れをなす\nわけにはいかない。絶対に…！", 2, 101403, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (56, 101401, "カスミ", "", "vo_empress_101401_004", 5, "vo_empress_101401_004", "", 1, "どんな哀しみでさえ、道理を穢す\n理由にしてはならない。さあ、\nお縄につくんだ。史上最大の迷宮\n事件…終わらせるのは…この私だ！", 3, 101402, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (57, 0, "ミサト", "", "vo_empress_101501_001", 5, "vo_empress_101501_001", "", 1, "先生は…ううん、先生たちは。\n絶対に負けません。みんなに傷一つ\nつけさせたりはしないわ…！", 1, 101501, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (58, 0, "ミサト", "", "vo_empress_101501_002", 5, "vo_empress_101501_002", "", 1, "とっても強大な敵ばかりね…\nでも、大丈夫。焦らず落ち着いて\n戦いましょう。先生がついてるわ\n長引いても、あきらめないで…！", 1, 101501, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (59, 0, "ミサト", "", "vo_empress_101501_003", 5, "vo_empress_101501_003", "", 1, "幻境竜后さんの力…すごいわ…\nううん、怖がってる暇なんてないの\n森のみんなを守るためにも…！\n好き勝手したら「めっ」ですからね", 2, 101501, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (60, 101501, "ミサト", "", "vo_empress_101501_004", 5, "vo_empress_101501_004", "", 1, "あなたと一緒なら\n負けたりなんか絶対にしないわ\n最後の一撃まで、\nがんばりましょうね♪", 3, 101502, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (61, 0, "スズナ", "", "vo_empress_101601_001", 5, "vo_empress_101601_001", "", 1, "ツヨそーな敵ばっかりで\nテン下げってカンジだけど\nとりま、うちとヒデサイが\n一緒なら乗り越えられるっしょ！", 1, 101601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (62, 0, "スズナ", "", "vo_empress_101601_002", 5, "vo_empress_101601_002", "", 1, "あっ、まってヒデサイ\nマントずれてるから直してあげる\n…よし！　こーゆう時こそ\nおしゃれでテン上げしなきゃね♪", 1, 101601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (63, 0, "スズナ", "", "vo_empress_101601_003", 5, "vo_empress_101601_003", "", 1, "おにヤバすぎて超わろ～…でもでも\nどうにかやるしかないっしょ～\n勝利のランウェイ遠すぎだけど\nうちら諦めんのはダメだよね～！", 2, 101601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (64, 101601, "スズナ", "", "vo_empress_101601_004", 5, "vo_empress_101601_004", "", 1, "アオハルでバイブス爆上げ♪\n今のうちらは、ムテキだよ～\nハッピーで、もにカワな未来だって\n一緒にゲットするしかないっしょ♪", 3, 101602, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (65, 0, "カオリ", "", "vo_empress_101701_001", 5, "vo_empress_101701_001", "", 1, "歌ったり踊ったり、\nキミと一緒にやりたいことが\nばんないあるからね～！\n絶対に負けられないさ～！", 1, 101701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (66, 0, "カオリ", "", "vo_empress_101701_002", 5, "vo_empress_101701_002", "", 1, "ううっ強そうな敵ばっかりさ～！\n長丁場の戦いにはやっぱりこれよ～\nサーターアンダギー！\n栄養付けて平和を守るさ～♪", 1, 101701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (67, 0, "カオリ", "", "vo_empress_101701_003", 5, "vo_empress_101701_003", "", 1, "うぅ～、幻境竜后、でーじ強いね～\n私たちも引き下がる気はないよ～！\nどんなに時間がかかっても、絶対に\n諦めたりしないさ～！　だよね～？", 2, 101703, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (68, 101701, "カオリ", "", "vo_empress_101701_004", 5, "vo_empress_101701_004", "", 1, "キミのくれた情熱が、\n私の中で熱く燃え滾ってるよ！\n最高の一撃、キミに見せるさ～！", 3, 101702, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (69, 0, "イオ", "", "vo_empress_101801_001", 5, "vo_empress_101801_001", "", 1, "学校生活の邪魔はさせないわ\nだって私、みんなの先生だもの\n明日の授業も世界のことも\n全部守ってみせるんだから！", 1, 101801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (70, 0, "イオ", "", "vo_empress_101801_002", 5, "vo_empress_101801_002", "", 1, "やん！　なんて手ごわい人たちなの\nでも諦めないわ。難しい問題だって\n落ち着いてやればちゃんと解けるの\n戦いも同じよ…いきましょう！", 1, 101801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (71, 0, "イオ", "", "vo_empress_101801_003", 5, "vo_empress_101801_003", "", 1, "これが、幻境竜后さんの力…圧倒\nされちゃいそう。でも、怖がってる\n場合じゃないわ。先生は絶対に、\nここから退かないわ！", 2, 101803, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (72, 101801, "イオ", "", "vo_empress_101801_004", 5, "vo_empress_101801_004", "", 1, "二人の絆があれば、\n怖いものなんてないわ\n先生と力を合わせて─\nいきましょう♪", 3, 101802, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (73, 0, "ミミ", "", "vo_empress_102001_001", 5, "vo_empress_102001_001", "", 1, "す、すごく強そうな人がいっぱい…\nミミ、怖くてぶるぶるしちゃうけど\nでも泣いちゃったりはしないよっ\nおにいちゃんがいっしょだもん…！", 1, 102003, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (74, 0, "ミミ", "", "vo_empress_102001_002", 5, "vo_empress_102001_002", "", 1, "プチグリフォンさんもハナちゃんも\nみゅ～ちゃんも…きっとみんな、\nミミのこと応援してくれてるよね\nだからミミも、がんばるよっ…！", 1, 102003, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (75, 0, "ミミ", "", "vo_empress_102001_003", 5, "vo_empress_102001_003", "", 1, "あ、あの竜の人…本気になったら、\nすごく強そうだよ…！このままじゃ\nみんなもミミたちも負けちゃう…？\nやだ、ミミそんなのいやだよっ…", 2, 102003, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (76, 102001, "ミミ", "", "vo_empress_102001_004", 5, "vo_empress_102001_004", "", 1, "おにいちゃんがくれた元気、\n今度はミミたちから届けようね\nもう大丈夫、心配しないでって…\n世界中の、大切なお友だちに…！", 3, 102002, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (77, 0, "クルミ", "", "vo_empress_102101_001", 5, "vo_empress_102101_001", "", 1, "怖い人たちがいっぱいですぅ…！\n…でも、みんな頑張ってる…私も\nベルルちゃんみたいに勇気を出して\n…祝福の音を鳴らしましょう！", 1, 102101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (78, 0, "クルミ", "", "vo_empress_102101_002", 5, "vo_empress_102101_002", "", 1, "お兄ちゃん、私、がんばりますぅ\n『ロスト』したお父さんたちの\nためにも…！　怖い時こそ前を見て\n戦ってみせますからっ…！", 1, 102101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (79, 0, "クルミ", "", "vo_empress_102101_003", 5, "vo_empress_102101_003", "", 1, "っ…すごい迫力ですぅ…！\nでも…絶望は必ず乗り越えられる\n胸の中の、希望の音色を信じて…\n逃げたりなんか、しませんよぅ…っ", 2, 102101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (80, 102101, "クルミ", "", "vo_empress_102101_004", 5, "vo_empress_102101_004", "", 1, "みんなに勇気を与えるために\n主役にも英雄にもなってみせますぅ\nお兄ちゃんがいてくれるなら\n私はなんでもできるんです…！", 3, 102102, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (81, 0, "ヨリ", "", "vo_empress_102201_001", 5, "vo_empress_102201_001", "", 1, "こ、これくらいの敵、問題ないわ！\nほんとはちょっと怖いけど…\nゲームの世界を救うことくらい\nこっちは慣れっこなんだから…！", 1, 102201, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (82, 0, "ヨリ", "", "vo_empress_102201_002", 5, "vo_empress_102201_002", "", 1, "ここで私たちが負けたら、\n世界が終わっちゃうなんて…\n絶対に認めるわけにはいかないわ！\nアンタも覚悟決めなさいよっ！", 1, 102201, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (83, 0, "ヨリ", "", "vo_empress_102201_003", 5, "vo_empress_102201_003", "", 1, "ここからが本当の戦いってこと？\nならもう、とことんやってやるわ！\nゲーマーってのは、敵が手強いほど\n燃えてくる生き物なのよ！", 2, 102203, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (84, 102201, "ヨリ", "", "vo_empress_102201_004", 5, "vo_empress_102201_004", "", 1, "絶対に帰りたい理由ができた…\nそう思うだけで、いくらでも力が\n湧いてくるの。これならもう、\n文句なしの勝ち確よねっ！", 3, 102202, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (85, 0, "アヤネ", "", "vo_empress_102301_001", 5, "vo_empress_102301_001", "", 1, "私もみんなと一緒に戦うよ！\n悪い人たちはフルスイングで\nあっという間に倒しちゃうから！\n『おうっ！　全員かかってこい！』", 1, 102301, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (86, 0, "アヤネ", "", "vo_empress_102301_002", 5, "vo_empress_102301_002", "", 1, "本当はちょっとだけ怖いけど…\nぷうきちもお兄ちゃんも一緒だもん\n力を合わせて世界を守っちゃうよ\n絶対に負けないんだから！", 1, 102303, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (87, 0, "アヤネ", "", "vo_empress_102301_003", 5, "vo_empress_102301_003", "", 1, "ううっあの人、すごく怖いけど\n逃げないよ、戦うって決めたもん\nね、お兄ちゃん、ぷうきち！\n『ここが踏ん張りどころだぞ！』", 2, 102303, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (88, 102301, "アヤネ", "", "vo_empress_102301_004", 5, "vo_empress_102301_004", "", 1, "お兄ちゃんが約束してくれたもん\n今の私ならどんな悪いやつにも\n負けないよ！　宇宙人でもなんでも\n一撃で追い返しちゃうんだから♪", 3, 102302, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (89, 0, "スズメ", "", "vo_empress_102501_001", 5, "vo_empress_102501_001", "", 1, "大変なことになっちゃいましたね…\nで、でも怖がっていられません！\nお嬢さまのことも、あなたのことも\n私が精一杯お支えします！", 1, 102503, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (90, 0, "スズメ", "", "vo_empress_102501_002", 5, "vo_empress_102501_002", "", 1, "世界の命運がかかってますから\nドジなんてしてられません！\n…って、ああっ！　言ったそばから\nまた魔法が暴走しちゃいましたっ！", 1, 102503, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (91, 0, "スズメ", "", "vo_empress_102501_003", 5, "vo_empress_102501_003", "", 1, "す、すごい力です…！\nでもお嬢さまや大切な人をおいて\n逃げるわけにはいきません！\nどこまでもお供します…！", 2, 102503, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (92, 102501, "スズメ", "", "vo_empress_102501_004", 5, "vo_empress_102501_004", "", 1, "大切な人と力を合わせれば、\nドジな私でも世界を救えるんです！\n世界規模…いえ、宇宙規模の大掃除\n始めちゃいますよ～っ！", 3, 102502, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (93, 0, "リン", "", "vo_empress_102601_001", 5, "vo_empress_102601_001", "", 1, "ええー？　こんだけ人数いるならさ\n一人ぐらいいなくても…\n…って空気じゃないわけね\nはいはい、あたしも働きますよー", 1, 102603, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (94, 0, "リン", "", "vo_empress_102601_002", 5, "vo_empress_102601_002", "", 1, "うぅ…あんなのもうバグでしょ！？\nこんな無理ゲーに参戦したんだもん\n終わったらしばらく働かないから！\nダラダラゴロゴロするからね～！", 1, 102603, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (95, 0, "リン", "", "vo_empress_102601_003", 5, "vo_empress_102601_003", "", 1, "見てよあのビジュアルさー\nまさにラスボスって感じじゃん…\nでも、どんなゲームでもボスは\n倒せるわけだし…はぁ、やるかー", 2, 102603, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (96, 102601, "リン", "", "vo_empress_102601_004", 5, "vo_empress_102601_004", "", 1, "ここまで来たら後には退けないし\n正真正銘のラスボス戦ってんなら\nあたしも─気合い入れて\n少しぐらいイイとこ見せないとね！", 3, 102602, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (97, 0, "エリコ", "", "vo_empress_102701_001", 5, "vo_empress_102701_001", "", 1, "有象無象のクズ虫が、私たちの\n幸せを阻もうとしているようですね\nあぁ、なんて忌々しいのでしょう…\n残らずすり潰しますわ、クスクス…", 1, 102701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (98, 0, "エリコ", "", "vo_empress_102701_002", 5, "vo_empress_102701_002", "", 1, "クスクス…あら、失礼しましたわ\nこの連中を駆逐すれば、私たちの\n絆はより強く…そんな想像をしたら\n思わず…クスクスクス、クスクス", 1, 102701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (99, 0, "エリコ", "", "vo_empress_102701_003", 5, "vo_empress_102701_003", "", 1, "あの女…下らない言葉であなた様を\n誑かそうとしたとか。万死に値する\n罪…身の程を思い知らせてやるまで\n決して退きはしませんわ…", 2, 102703, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (100, 102701, "エリコ", "", "vo_empress_102701_004", 5, "vo_empress_102701_004", "", 1, "『壊し屋』と呼ばれる私ですが…\n今はこの力、創るために振るいます\nあなた様との愛、未来…\nクスクス…さあ参りましょう…♪", 3, 102702, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (101, 0, "サレン", "", "vo_empress_102801_001", 5, "vo_empress_102801_001", "", 1, "しっかり頭数揃えてきたわね…\nでもこの程度の力に屈するような\nあたしたちじゃないんだから\nあんたも、サポート頼んだわよ！", 1, 102801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (102, 0, "サレン", 10000, "vo_empress_102801_002", 3, "vo_empress_102801_002", 1, 1, "ちょっと！　なんか向こうに\n教育に悪そうなのがいるんだけど！\nあいつは子どもたちの目に入る前に\nあたしたちで倒すわよ。いい？", 4002, 102801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (103, 0, "サレン", "", "vo_empress_102801_003", 5, "vo_empress_102801_003", "", 1, "もう、強すぎて参っちゃうわね…\nでも諦めるわけにはいかないわ\nこっちだって守らなきゃいけない\nものがたくさんあるんだから！", 2, 102803, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (104, 102801, "サレン", "", "vo_empress_102801_004", 5, "vo_empress_102801_004", "", 1, "いつも以上に負ける気がしないわ\nこれもあんたと気持ちが通じた\nおかげね。あんたが側にいる限り、\nあたしはずっと無敵なんだから！", 3, 102802, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (105, 0, "ノゾミ", "", "vo_empress_102901_001", 5, "vo_empress_102901_001", "", 1, "この世界が終わっちゃうって…\nアイドル活動も卒業ってコト！？\nファンのみんなが黙ってないよ！\nもちろん私だって…！", 1, 102903, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (106, 0, "ノゾミ", "", "vo_empress_102901_002", 5, "vo_empress_102901_002", "", 1, "どんな強い敵にだって屈しない…\n歌って踊って戦うアイドルになる！\nあの日に誓った願い、私の希望！\n今こそ、果たして見せるんだから！", 1, 102903, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (107, 0, "ノゾミ", "", "vo_empress_102901_003", 5, "vo_empress_102901_003", "", 1, "幻境竜后…ダンスも歌も、あなたに\nとって価値はないかもしれないけど\n私はこのステージから逃げたり\nなんてしない！　アイドルとして！", 2, 102903, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (108, 102901, "ノゾミ", "", "vo_empress_102901_004", 5, "vo_empress_102901_004", "", 1, "星を書き換えるなんてすごい発想…\nプロデューサーとか向いてるかも？\nって、今はそんな場合じゃないか！\n覚悟してよね、幻境竜后！", 3, 102901, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (109, 0, "ニノン", "", "vo_empress_103001_001", 5, "vo_empress_103001_001", "", 1, "ショーグンの天下統一を阻む者は\n誰であろうと許しまセン！\nショーグン！　ここはチューシン\nニノンにお任せアーレー！", 1, 103001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (110, 0, "ニノン", "", "vo_empress_103001_002", 5, "vo_empress_103001_002", "", 1, "むむむ…待ち受けているのは強敵\nばかり…それでも退きまセン！\n超烈火之紅蓮旋風で、\nまとめて討ち取ってみせまショウ！", 1, 103001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (111, 0, "ニノン", "", "vo_empress_103001_003", 5, "vo_empress_103001_003", "", 1, "な、なんて強さ…このままでは、\nワタシたちは負けてしまいます…\n…いいえ。いいえ！　ショーグンの\nためにも、諦めることなど…っ！", 2, 103003, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (112, 103001, "ニノン", "", "vo_empress_103001_004", 5, "vo_empress_103001_004", "", 1, "感じマス、ショーグンの愛を…！\n今ならどんな敵が来ても、\nカッサイ、ボンサイ、\nオチャノコサイサイデース！", 3, 103002, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (113, 0, "シノブ", "", "vo_empress_103101_001", 5, "vo_empress_103101_001", "", 1, "この世界が、明日を迎えることなく\n滅んでしまうかもしれない…\n運命の岐路が、目の前にあります\n抗えるのは、私たちだけです…！", 1, 103101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (114, 0, "シノブ", "", "vo_empress_103101_002", 5, "vo_empress_103101_002", "", 1, "何よりも色濃い死の気配が、\n世界に満ちていくのを感じます\nでも、倒れるわけにはいきません\n最後まで戦いましょう、全力で", 1, 103101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (115, 0, "シノブ", "", "vo_empress_103101_003", 5, "vo_empress_103101_003", "", 1, "これほどまでに強大な力なんて…\n占いも、未来は滅びの闇に覆われ\nつつある、と出ています…それでも\n希望を手放すわけには…！", 2, 103103, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (116, 103101, "シノブ", "", "vo_empress_103101_004", 5, "vo_empress_103101_004", "", 1, "命ある者にとって、死の運命は\n決して避けられないもの…\nでも、今この時ではないはずです\n戦いましょう、未来のために…！", 3, 103101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (117, 0, "アキノ", "", "vo_empress_103201_001", 5, "vo_empress_103201_001", "", 1, "これ以上の狼藉は許しません！\nウィスタリア家の名に懸けて、\nこの世界の人々を守ります…必ずや\n貴人としての役目を果たしますわ！", 1, 103201, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (118, 0, "アキノ", "", "vo_empress_103201_002", 5, "vo_empress_103201_002", "", 1, "互いを利するウィンウィンの関係\nそれが商売の鉄則です。力を振るい\n一方的に望みを押し付けるなんて、\n倒産まっしぐらですわよっ！", 1, 103201, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (119, 0, "アキノ", "", "vo_empress_103201_003", 5, "vo_empress_103201_003", "", 1, "幻境竜后…すさまじい力ですわね\n世界を意のままにするという野望も\n決して絵空事ではないのでしょう…\nそれでも私は…諦めませんわよ！", 2, 103203, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (120, 103201, "アキノ", "", "vo_empress_103201_004", 5, "vo_empress_103201_004", "", 1, "人々を守ることが力ある者の務め…\nそしてあなたさまと共に生きること\nそれが私の務めであり願いですわ！\nこの想いは、止まりませんわよ！", 3, 103202, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (121, 0, "マヒル", "", "vo_empress_103301_001", 5, "vo_empress_103301_001", "", 1, "こんな舞台で漫才したって\nみんなもお天道さんもどんよりだべ\n安心して笑ってられる世界を\nオラたちで取り戻すど！　おー！", 1, 103301, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (122, 0, "マヒル", "", "vo_empress_103301_002", 5, "vo_empress_103301_002", "", 1, "お、おっかねぇ連中だ…！\nでも…スベっちまう怖さに比べりゃ\nマシだべな！　あははっ！\nみんなの笑顔は、オラが守るべ！", 1, 103301, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (123, 0, "マヒル", "", "vo_empress_103301_003", 5, "vo_empress_103301_003", "", 1, "あの子、芸人として光りそうだべな\n幻境竜后なんて仰々しい名前も…\nノーヴィジョンズノープロブレム！\n…あたた！　激しいツッコミだべ！", 2, 103303, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (124, 103301, "マヒル", "", "vo_empress_103301_004", 5, "vo_empress_103301_004", "", 1, "逆境も笑顔で切り開く…\nあんちゃんと一緒なら\nできる気がすんだ\nオラたちの芸人魂、見せてやるべ！", 3, 103302, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (125, 0, "ユカリ", "", "vo_empress_103401_001", 5, "vo_empress_103401_001", "", 1, "元…ううん、正しき聖騎士として\nここでやらなきゃいつやるのよ…！\n必ずみんなを守りきってみせるわ\n怪我をした人は私のところへ！", 1, 103401, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (126, 0, "ユカリ", "", "vo_empress_103401_002", 5, "vo_empress_103401_002", "", 1, "…んぐっ…ごくっ…ぷは～っ♪\nよぉし気合十分らわ～っ！\nこら～幻境竜后～っ！　隠れて\nないでかかってきなさ～い！", 1, 103401, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (127, 0, "ユカリ", "", "vo_empress_103401_003", 5, "vo_empress_103401_003", "", 1, "ひっく…ふぇ？　な、なに……？\nと、とっても大きいのが見えりゅ…\n…なっ、なによこれえぇぇ！\nこ、これが幻境竜后の姿なのぉ～っ", 2, 103403, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (128, 103401, "ユカリ", "", "vo_empress_103401_004", 5, "vo_empress_103401_004", "", 1, "私は無敵らのよ～♪　この世界と\nキミと築く\n素敵な未来のために…幻境竜后！\nぶっとばしてやるわぁ～っ！", 3, 103402, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (129, 0, "キョウカ", "", "vo_empress_103601_001", 5, "vo_empress_103601_001", "", 1, "ここで私たちが諦めたら、このまま\n世界が終わっちゃう！　そんなの\n絶対ダメです！　負けられません！\n私たちで全部退治しちゃいますよ！", 1, 103603, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (130, 0, "キョウカ", "", "vo_empress_103601_002", 5, "vo_empress_103601_002", "", 1, "うぅ、ふしんしゃがいっぱいです！\n…でも、このくらいへっちゃらです\nお母さんが心配する前に、早く\n片付けておうちに帰りましょう！", 1, 103603, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (131, 0, "キョウカ", "", "vo_empress_103601_003", 5, "vo_empress_103601_003", "", 1, "あれが私たちの敵、幻境竜后…\nほ、本当に勝てるんでしょうか…？\n立ってるだけで体が震えて…でも、\n弱気になっちゃダメですよねっ…！", 2, 103601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (132, 103601, "キョウカ", "", "vo_empress_103601_004", 5, "vo_empress_103601_004", "", 1, "正直に言うと…まだ少し怖いです\n我慢したって怖くて体が震えます\nでも、あなたがいてくれるから…\n勇気だって同じくらい湧いてきます", 3, 103602, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (133, 0, "トモ", "", "vo_empress_103701_001", 5, "vo_empress_103701_001", "", 1, "滅ぼすための力に、守るための力が\n屈するわけにはいかないよ。\nこの剣の誇りに賭けて、必ず止める\nさあ、来い！　ミクマ流が相手だ！", 1, 103701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (134, 0, "トモ", "", "vo_empress_103701_002", 5, "vo_empress_103701_002", "", 1, "追いかけっこでもしようか\n鬼さんこちら♪　…って、まだ\n来るの！？　不意打ちされる側に\nなるのは趣味じゃないんだけどな！", 1, 103701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (135, 0, "トモ", "", "vo_empress_103701_003", 5, "vo_empress_103701_003", "", 1, "踏み込めない…踏み込む隙がない…\n向きあってるだけで精一杯なんて…\nで、でも…こんなところで\n剣を捨てるわけにはっ…！", 2, 103701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (136, 103701, "トモ", "", "vo_empress_103701_004", 5, "vo_empress_103701_004", "", 1, "勝機は私の中にあったんだ…！\nあなたとの、\n一番強くて絶対に消えない絆\nそれが、あいつを倒す力をくれる！", 3, 103702, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (137, 0, "シオリ", "", "vo_empress_103801_001", 5, "vo_empress_103801_001", "", 1, "手ごわい相手ですね…\nでも、不思議と怖くありません\nあなたと力を合わせれば\n何とかなるって信じていますから", 1, 103801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (138, 0, "シオリ", "", "vo_empress_103801_002", 5, "vo_empress_103801_002", "", 1, "あなたの応援で、私の胸に\n愛と希望が満ち溢れています…\n今こそ魔法狩人ピュアリー★シオリ\nに大変身する時なのかも…？", 1, 103801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (139, 0, "シオリ", "", "vo_empress_103801_003", 5, "vo_empress_103801_003", "", 1, "とてつもない力ですね…\nでも、諦めたくありません\n何度だって立ち上がってみせます\n今までと同じように…！", 2, 103803, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (140, 103801, "シオリ", "", "vo_empress_103801_004", 5, "vo_empress_103801_004", "", 1, "今の私に怖いものなんてありません\nあなたとの愛の力がありますから♪\n…少し舞い上がり過ぎですかね？\nふふ、気を引き締めてがんばります", 3, 103802, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (141, 0, "アオイ", "", "vo_empress_104001_001", 5, "vo_empress_104001_001", "", 1, "進んで目立ちたくはないですけど…\nと、ともっ…友達を守るためなら！\nＢＢ団として、勇気を振り絞って…\n団長さんと一緒に戦います！", 1, 104001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (142, 0, "アオイ", "", "vo_empress_104001_002", 5, "vo_empress_104001_002", "", 1, "いいい、一緒に戦う仲間がこんなに\nいてくれるなんて、こ、心強いの\n助太郎～っ！　私も末席で参加し…\nじゃなくてっ！　全力で戦います！", 1, 104002, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (143, 0, "アオイ", "", "vo_empress_104001_003", 5, "vo_empress_104001_003", "", 1, "ううっ、手も足も声も震えてます…\nで、でも逃げも隠れもしませんよっ\n逃げたらぼっちが廃ります！", 2, 104003, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (144, 104001, "アオイ", "", "vo_empress_104001_004", 5, "vo_empress_104001_004", "", 1, "私はひとりぼっちじゃない…\n団長さんと繋がった絆があるから\nどんな敵だって怖くないですっ！\n行きましょう、団長さんっ！", 3, 104002, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (145, 0, "チカ", "", "vo_empress_104201_001", 5, "vo_empress_104201_001", "", 1, "やめてくれる気はなさそうです\nそれなら私も、絶対にここを\n動きはしません…！　だって\n私は……ワガママですからっ！", 1, 104203, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (146, 0, "チカ", "", "vo_empress_104201_002", 5, "vo_empress_104201_002", "", 1, "私の唱喚術は人を守るためのもの…\nこの世界の森羅万象を護るための\nもの。今こそ、声の限り歌います\nこの子たちと、あなたと共に！", 1, 104201, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (147, 0, "チカ", "", "vo_empress_104201_003", 5, "vo_empress_104201_003", "", 1, "精霊たちが震えてる…今までの\n敵とは訳が違うってことですよね…\n私もここに立っているのが精一杯…\n怖いけど…でも！　退きません…！", 2, 104203, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (148, 104201, "チカ", "", "vo_empress_104201_004", 5, "vo_empress_104201_004", "", 1, "今なら歌える気がします。ずっと\n探していた、誰かの心を震わせる歌\n幻境竜后…孤独なあなたの心にも\n私たちの歌が届くように…！", 3, 104201, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (149, 0, "マコト", "", "vo_empress_104301_001", 5, "vo_empress_104301_001", "", 1, "敵さんがどんだけ強くったって\n後には退けねぇんだ！　そうだろ、\nさぁ、覚悟しやがれよ！", 1, 104301, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (150, 0, "マコト", "", "vo_empress_104301_002", 5, "vo_empress_104301_002", "", 1, "くっ、敵の連中、ずいぶんな戦力\n揃えてきやがった。けど、\n数でも気合でも負けやしねぇ！\nあたしが嚙み砕いてやる！", 1, 104301, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (151, 0, "マコト", "", "vo_empress_104301_003", 5, "vo_empress_104301_003", "", 1, "幻境竜后とやら…マジで\n洒落になんねえな。だからって\n引き下がるわけにゃいかねえ！\n持ちこたえてやるぜ！", 2, 104303, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (152, 104301, "マコト", "", "vo_empress_104301_004", 5, "vo_empress_104301_004", "", 1, "どんな強い敵でも\n恐れる必要なんてないよな\nさあ、いっしょに─最大パワーで\nブチのめしてやろうぜっ！", 3, 104302, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (153, 0, "イリヤ", "", "vo_empress_104401_001", 5, "vo_empress_104401_001", "", 1, "ここはいずれわらわが支配する世界\nつまり、わが領地に等しきもの…\n奴らのような不届き者の蛮行、\n見過ごすわけにはいかぬわ！", 1, 104401, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (154, 0, "イリヤ", "", "vo_empress_104401_002", 5, "vo_empress_104401_002", "", 1, "厳しい戦いになりそうじゃな…\nお主もわらわから離れるでないぞ\nも、もちろん、大人の姿を保つのに\n都合がいいからというだけじゃ！", 1, 104401, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (155, 0, "イリヤ", "", "vo_empress_104401_003", 5, "vo_empress_104401_003", "", 1, "何とも恐ろしく禍々しい力じゃ…\nだが、我が意志は決して挫けぬ\n高貴なる吸血鬼の誇りに懸けて、\n最後まで戦い抜いてみせようぞ", 2, 104401, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (156, 104401, "イリヤ", "", "vo_empress_104401_004", 5, "vo_empress_104401_004", "", 1, "己が誰を敵に回したのかを、\n骨の髄まで知らしめてやろうぞ\nここにいるのは固き絆で結ばれし\n伝説の吸血鬼とその眷属じゃ！", 3, 104401, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (157, 0, "クウカ", "", "vo_empress_104501_001", 5, "vo_empress_104501_001", "", 1, "とっても強そうな敵ですっ…\n当然、攻撃も強烈になるはず…\nドＳさん、ここはどうかクウカに、\n先頭をお任せください！　ぐふふ♪", 1, 104501, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (158, 0, "クウカ", "", "vo_empress_104501_002", 5, "vo_empress_104501_002", "", 1, "安心してドＳさんに虐げてもらう\nためにもクウカは負けられませんっ\nこの世界で一番のドＭとして、\n全力で責められに行ってきますっ！", 1, 104501, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (159, 0, "クウカ", "", "vo_empress_104501_003", 5, "vo_empress_104501_003", "", 1, "ううっ、刺激が強すぎますよ…っ\nだけど、ドＭのプライドにかけて\nここで退くわけにはいきませんっ！\nドＳさんのこと、守り抜きます…っ", 2, 104503, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (160, 104501, "クウカ", "", "vo_empress_104501_004", 5, "vo_empress_104501_004", "", 1, "その視線は、『全部終わったらたっ\nぷり調教してやるからな』という\n意味ですね！　ぐふふっ…♪　負け\nられない理由がまた一つできました", 3, 104502, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (161, 0, "タマキ", "", "vo_empress_104601_001", 5, "vo_empress_104601_001", "", 1, "強そうなやつらが目白押しにゃ～\n短期戦でどうにかならないなら…\n長丁場に向けて、特別価格の\nたい焼きはいかがかにゃ～？", 1, 104601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (162, 0, "タマキ", "", "vo_empress_104601_002", 5, "vo_empress_104601_002", "", 1, "ファントムキャッツは\n狙った獲物を逃がさないにゃ！\nあたしたちの未来を手に入れるまで\nとことんやってやるにゃ～！", 1, 104601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (163, 0, "タマキ", "", "vo_empress_104601_003", 5, "vo_empress_104601_003", "", 1, "にゃにゃっ、これが幻境竜后…\nとんでもない力だにゃ\nでも、ここで逃げたらファントム\nキャッツの名が廃るにゃ～！", 2, 104603, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (164, 104601, "タマキ", "", "vo_empress_104601_004", 5, "vo_empress_104601_004", "", 1, "ファントムキャッツにかかれば\nどんなに強い悪党でも\n滅びる運命にゃ！\nとっておきの一撃、キメるにゃ～！", 3, 104602, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (165, 0, "ジュン", "", "vo_empress_104701_001", 5, "vo_empress_104701_001", "", 1, "全軍展開！　敵の一体たりとも\nこの先へは進ませるな\n苦しいときは、私の背中を見るんだ\n我々は決して折れはしない！", 1, 104701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (166, 0, "ジュン", "", "vo_empress_104701_002", 5, "vo_empress_104701_002", "", 1, "少年…\n最前線は危険だが、下がるつもりは\nないのか？　ふふ、やはり強情だな\nならば、私の隣を絶対に離れるな", 1, 104701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (167, 0, "ジュン", "", "vo_empress_104701_003", 5, "vo_empress_104701_003", "", 1, "な…なんだ…この冷たい闘気は…！\nみんな、いったん退がれ！\n安心しろ、ここは私が防ぎきる\n…たとえ…この身に代えても", 2, 104701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (168, 104701, "ジュン", "", "vo_empress_104701_004", 5, "vo_empress_104701_004", "", 1, "幻境竜后、貴様は絶対に勝てないよ\n自分の身以上に、大切な誰かを\n守りたいという、人間の持つ尊い\n想いを、知ることのない貴様は…！", 3, 104701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (169, 0, "ミフユ", "", "vo_empress_104801_001", 5, "vo_empress_104801_001", "", 1, "バイト仲間とこの世界のみんなを\n守るために！　私たちのやるべき\nことはただ一つ！　いいわね？\n─最高の効率で倒すわよ！", 1, 104801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (170, 0, "ミフユ", "", "vo_empress_104801_002", 5, "vo_empress_104801_002", "", 1, "相手も数が多いし、短期決戦とは\nいかないわね…って！　早く\n勝たなきゃバイトに遅刻しちゃう\nもっと効率アップしていくわよ！", 1, 104801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (171, 0, "ミフユ", "", "vo_empress_104801_003", 5, "vo_empress_104801_003", "", 1, "幻境竜后……本当に圧倒的な力ね\nだからってそう簡単に諦められる\nわけはないわよね。たとえそれが\n非効率的な判断だとしても……！", 2, 104803, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (172, 104801, "ミフユ", "", "vo_empress_104801_004", 5, "vo_empress_104801_004", "", 1, "こんなに迂遠で非効率的な計画を\n立てる敵になんて負けないわ！\n効率を極めた私たちの一撃を\n叩きつけてやりましょう！", 3, 104802, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (173, 0, "シズル", "", "vo_empress_104901_001", 5, "vo_empress_104901_001", "", 1, "安心していいよ、弟くん♪\n弟くんには指一本触れさせない！\n絶対に弟くんを守るから…だって\nそれがお姉ちゃんの役目だもんね！", 1, 104902, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (174, 0, "シズル", "", "vo_empress_104901_002", 5, "vo_empress_104901_002", "", 1, "準備はできてる、弟くん？\n不安なら手をつないであげよっか？\n大丈夫、お姉ちゃんと弟くんなら\n悪いやつらを全部倒せるはず♪", 1, 104902, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (175, 0, "シズル", "", "vo_empress_104901_003", 5, "vo_empress_104901_003", "", 1, "幻境竜后…手強そうだね…\nでも諦めないよ、絶対に！\n弟くんとお姉ちゃんの大切な世界\nきっと守り抜いてみせるんだから！", 2, 104903, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (176, 104901, "シズル", "", "vo_empress_104901_004", 5, "vo_empress_104901_004", "", 1, "お姉ちゃんと弟くんの力を合わせて\n二人の未来を、みんなの未来を\n一緒に守ろっ！　あ、終わったら\nたくさん甘えさせてあげるからね♪", 3, 104902, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (177, 0, "ミサキ", "", "vo_empress_105001_001", 5, "vo_empress_105001_001", "", 1, "アブナイキレイなお姉さんはね\n『ふれーばー』だから許されるの！\nこんなメチャクチャにするなんて…\n本物の大人のレディが勝負よ勝負！", 1, 105001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (178, 0, "ミサキ", "", "vo_empress_105001_002", 5, "vo_empress_105001_002", "", 1, "アタシは全世界代表の\n大人のレディなんだから！\nアンタ！\nしっかりエスコートしてよね！", 1, 105001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (179, 0, "ミサキ", "", "vo_empress_105001_003", 5, "vo_empress_105001_003", "", 1, "コ、コイツが幻境竜后…っ\n…正直怖いけど…絶対に逃げないわ\n大人のレディのプライドにかけて\n戦い抜いてやるんだから…！", 2, 105003, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (180, 105001, "ミサキ", "", "vo_empress_105001_004", 5, "vo_empress_105001_004", "", 1, "終わったらデートよ！　だって…\n約束があった方がやる気出るもん♪\nよーし！　大人のレディとして\n最後はエレガントに決めるわよ！", 3, 105002, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (181, 0, "ミツキ", "", "vo_empress_105101_001", 5, "vo_empress_105101_001", "", 1, "なんて重圧かしら…でも、あいにく\n私も伊達に修羅場をくぐってないの\nさあ、かかってきなさい！\n裏の人生経験、見せてあげるわ…♪", 1, 105101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (182, 0, "ミツキ", "", "vo_empress_105101_002", 5, "vo_empress_105101_002", "", 1, "私は闇医者である前に科学者なの\nあなたたち、実験に協力してくれる\nわよね？　隻眼の悪魔の名は\n伊達じゃないのよ？　覚悟しなさい", 1, 105101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (183, 0, "ミツキ", "", "vo_empress_105101_003", 5, "vo_empress_105101_003", "", 1, "到底不可能に思える挑戦こそ\n科学者の腕の見せどころなのよ\n青い薔薇のごとく、人の信念が\n起こす奇跡を見せてあげるわ…！", 2, 105101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (184, 105101, "ミツキ", "", "vo_empress_105101_004", 5, "vo_empress_105101_004", "", 1, "迷いのない言葉をもらったんだもの\n私だってもう、覚悟を決めたわ\nこの先の未来を君と生きていく…\nそのために全力をぶつけるだけよ！", 3, 105101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (185, 0, "リマ", "", "vo_empress_105201_001", 5, "vo_empress_105201_001", "", 1, "私のお友達をいじめるなら\n相手になるわ！\nたとえ魔物に間違えられても\n絶対にここを引かないから！", 1, 105201, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (186, 0, "リマ", 10000, "vo_empress_105201_002", 3, "vo_empress_105201_002", 1, 1, "ね、ねぇ…\nちょっと聞きたいんだけど\n毛皮もないのにあの姿なのよね？\n風邪引いたりしないのかしら？", 4002, 105201, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (187, 0, "リマ", "", "vo_empress_105201_003", 5, "vo_empress_105201_003", "", 1, "ひづめは割れちゃいそうだし…\n毛並みだってボロボロだし…\nでも後ろには彼がいるんだもの\n恋する乙女の負けられない戦いよ！", 2, 105201, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (188, 105201, "リマ", "", "vo_empress_105201_004", 5, "vo_empress_105201_004", "", 1, "私はもう恋する女の子じゃないわ…\n王子様の愛を受け取ったお姫様よ！\n彼が私を守ってくれるように\n私が彼を守ってみせるわ！", 3, 105202, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (189, 0, "モニカ", "", "vo_empress_105301_001", 5, "vo_empress_105301_001", "", 1, "どれほど強大な敵であろうと、\n我々【ヴァイスフリューゲル\nランドソル支部】がいれば安心…\nこら！　皆纏まって行動しろー！", 1, 105303, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (190, 0, "モニカ", "", "vo_empress_105301_002", 5, "vo_empress_105301_002", "", 1, "敵戦力は強大無比…だが、\n私たちなら必ず倒せるはずだ！\n白き翼の名のもとに、今こそ\n正義の鉄槌を下してやる！", 1, 105301, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (191, 0, "モニカ", "", "vo_empress_105301_003", 5, "vo_empress_105301_003", "", 1, "これが幻境竜后の底力か…\n名にし負う圧倒的な強さだな…\nだが！　長期戦になろうとも必ずや\n私たちが勝利の旗を掲げるのだ！", 2, 105301, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (192, 105301, "モニカ", "", "vo_empress_105301_004", 5, "vo_empress_105301_004", "", 1, "貴公と一緒ならば\nなんだってできるとも\nさあ、最後の一撃を加えてやろう！", 3, 105302, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (193, 0, "ツムギ", "", "vo_empress_105401_001", 5, "vo_empress_105401_001", "", 1, "強そうな相手ばかりですけど\nだからなんだっていうんですか！\nほら、騎士さんも気合い入れて！\n一緒に戦いますよ！", 1, 105401, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (194, 0, "ツムギ", 10000, "vo_empress_105401_002", 3, "vo_empress_105401_002", 1, 1, "なんか敵に下着姿…っていうか\nほぼ裸みたいな人いません？\n…え？　あれ趣味なんですか？\nあの人の？　…正気ですか？", 4002, 105403, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (195, 0, "ツムギ", "", "vo_empress_105401_003", 5, "vo_empress_105401_003", "", 1, "世界を作り変えようなんて\n幻境竜后、絶対許せません…！\nあとその服！　そんなに破いて！\nデザイナーが泣いてますよ！", 2, 105403, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (196, 105401, "ツムギ", "", "vo_empress_105401_004", 5, "vo_empress_105401_004", "", 1, "私と騎士さんの糸は\n絶対に切れません！\nだから…今ここで\nすべてを終わらせましょう！", 3, 105401, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (197, 0, "アユミ", "", "vo_empress_105501_001", 5, "vo_empress_105501_001", "", 1, "つ、強そうな人たちばっかり…\n逃げたいくらいだけど、\nそれはダメ。先輩をケガさせない\nためにも、私も頑張らなくちゃ！", 1, 105503, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (198, 0, "アユミ", "", "vo_empress_105501_002", 5, "vo_empress_105501_002", "", 1, "私なんかが大それたことを言うのは\n笑われるかも…でも…！\n先輩を守るために、\n世界を守ってみせます…！", 1, 105501, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (199, 0, "アユミ", "", "vo_empress_105501_003", 5, "vo_empress_105501_003", "", 1, "な、なんて大きさ、存在感…！\nまるで私とは真逆の人…\nこうして立ってるだけで、\n私、消えちゃいそうです～っ…！", 2, 105503, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (200, 105501, "アユミ", "", "vo_empress_105501_004", 5, "vo_empress_105501_004", "", 1, "先輩がそばにいてくれる…\nそれだけで勇気が湧いてきて\n前へ進む力がもらえるんです\n行きましょう、先輩！", 3, 105502, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (201, 0, "ルカ", "", "vo_empress_105601_001", 5, "vo_empress_105601_001", "", 1, "雁首並べてよくもまあ…\nこりゃ長丁場になりそうだ\n釣りと同じくじっくり腰を据えて\n勝負しようじゃないか", 1, 105601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (202, 0, "ルカ", "", "vo_empress_105601_002", 5, "vo_empress_105601_002", "", 1, "世界の危機とあっちゃあ\nアタシたち黄昏時の住人でも\n黙っちゃいられないね！\nひとっ働きさせてもらおうかい！", 1, 105601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (203, 0, "ルカ", "", "vo_empress_105601_003", 5, "vo_empress_105601_003", "", 1, "へぇ、これが幻境竜后かい…\nたいそうな強さだけど、アタシも\nここで退くわけにはいかないんだ\n心に差した刃に懸けて、いくよ！", 2, 105603, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (204, 105601, "ルカ", "", "vo_empress_105601_004", 5, "vo_empress_105601_004", "", 1, "刀も恋も揃ったアタシは天下無双！\nお前さんが側にいてくれれば、\nどんな巨悪にだって勝てるよ！", 3, 105602, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (205, 0, "ペコリーヌ", "", "vo_empress_105801_001", 5, "vo_empress_105801_001", "", 1, "また一緒に、みんなで\nおいしいごはんを食べるために！\nわたしたちは、絶対に負けません！", 1, 105803, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (206, 0, "ペコリーヌ", 10000, "vo_empress_105801_002", 3, "vo_empress_105801_002", 1, 1, "フレイヤさんだけじゃなく、\n覇瞳皇帝やミロクまで！\n長丁場になりそうです…\n栄養補給はしっかりしましょうね！", 4003, 105801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (207, 0, "ペコリーヌ", "", "vo_empress_105801_003", 5, "vo_empress_105801_003", "", 1, "これが、幻境竜后の力…\nやばいですね。正直、どうやって\n止めればいいのか分かりません\nでもここで引き下がるわけには…っ", 2, 105803, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (208, 105801, "ペコリーヌ", "", "vo_empress_105801_004", 5, "vo_empress_105801_004", "", 1, "あなたの愛情でお腹いっぱいの\n無敵ペコリーヌ参上です☆\nわたしたちの明日を、この世界を\n全力全開で取り戻しましょう！", 3, 105802, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (209, 0, "コッコロ", "", "vo_empress_105901_001", 5, "vo_empress_105901_001", "", 1, "みなさまとのおいしいごはんのため\n負けるわけにはまいりません\n主さま、お背中はお任せください\nわたくしがお守りいたします！", 1, 105903, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (210, 0, "コッコロ", "", "vo_empress_105901_002", 5, "vo_empress_105901_002", "", 1, "敵は強大…ですが、心強い仲間の\nみなさまが一緒でございます\n…全員主さまとお知り合いなのは\n未だに信じられませんが…", 1, 105905, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (211, 0, "コッコロ", "", "vo_empress_105901_003", 5, "vo_empress_105901_003", "", 1, "まだこのような力が…！？\n主さま、ここはお下がりください\nたとえこの身に何があろうと、\nあなただけはお守りいたします…！", 2, 105903, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (212, 105901, "コッコロ", "", "vo_empress_105901_004", 5, "vo_empress_105901_004", "", 1, "主さまとの絆がある限り\nわたくしは絶対に負けません！\nいついかなるときも、何があろうと\nわたくしが導いてみせます！", 3, 105902, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (213, 0, "キャル", 10000, "vo_empress_106001_001", 3, "vo_empress_106001_001", 1, 1, "また陛下と戦うのね…大丈夫、一番\n大事なものが何なのかは分かってる\n…だから、あたしも負けないわ\n─陛下、よろしくお願いします！", 4005, 106001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (214, 0, "キャル", "", "vo_empress_106001_002", 5, "vo_empress_106001_002", "", 1, "この世界を好き勝手しようだなんて\nそういう連中に人生振り回されるの\nこちとらもううんざりなのよ！\n全員ぶっ飛ばしてやるんだから！", 1, 106003, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (215, 0, "キャル", "", "vo_empress_106001_003", 5, "vo_empress_106001_003", "", 1, "なんなのよあの力、反則でしょ…\nだけどさ、どんなに怖くたって\nあたしはここから退かないわ\n他に行くとこも、ないんだからっ…", 2, 106003, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (216, 106001, "キャル", "", "vo_empress_106001_004", 5, "vo_empress_106001_004", "", 1, "絆の力でパワーアップ、なんて\nガラじゃないと思ってたけど…\n今だけは調子に乗らせてもらうわ\nもう負ける気がしないってねっ！", 3, 106002, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (217, 0, "ノウェム", "", "vo_empress_106101_001", 5, "vo_empress_106101_001", "", 1, "晶に直してもらって\n天楼覇断剣も新品同然だ！\n気合い入れていくぞオクトー！\nはーっはっはっはー！", 1, 106102, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (218, 0, "ノウェム", "", "vo_empress_106101_002", 5, "vo_empress_106101_002", "", 1, "真那、覚悟しとけよ！\nオマエが積み上げてきた悪事…\nこの大悪党がまとめて\nぶっ壊してやるからな！", 1, 106101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (219, 0, "ノウェム", "", "vo_empress_106101_003", 5, "vo_empress_106101_003", "", 1, "今までの借り…ここでまとめて\n返してやるって、決めてたんだ\nオマエだけは絶対に、許さない\n…オマエが、どれだけ強くても…っ", 2, 106103, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (220, 106101, "ノウェム", "", "vo_empress_106101_004", 5, "vo_empress_106101_004", "", 1, "大悪党のプリンセス？\nなんだかよくわからないけど──\nとにかく、あの化け物ぶった斬りに\n行くぞ！　ついてこい！", 3, 106102, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (221, 0, "シェフィ", "", "vo_empress_106401_001", 5, "vo_empress_106401_001", "", 1, "絶対に負けられない戦いね\nおいしいごはんと、本当の\nハッピーエンドのために\n気を引き締めていきましょう", 1, 106401, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (222, 0, "シェフィ", 10000, "vo_empress_106401_002", 3, "vo_empress_106401_002", 1, 1, "ミロク…まだ生きていたのね…！\nあの男は私が相手するわ\n兄さんの分もまとめて、\n今ここで借りを返さないと！", 4004, 106403, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (223, 0, "シェフィ", "", "vo_empress_106401_003", 5, "vo_empress_106401_003", "", 1, "こんな力を隠してたなんて…！\n…まだよ。まだ諦めないわ\nどんな方法を使ってでも\nみんなだけは助けてみせる…！", 2, 106401, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (224, 106401, "シェフィ", "", "vo_empress_106401_004", 5, "vo_empress_106401_004", "", 1, "不思議ね…あなたとの思い出で\n全身に力が満ちていくような気持ち\n…私たちが紡いできた絆を\n幻境竜后に見せてやりましょう", 3, 106402, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (225, 0, "カヤ", "", "vo_empress_106501_001", 5, "vo_empress_106501_001", "", 1, "おまえら、ケンカ売りたいんだろ？\nこの世界そのものに！\nならこっち向けよ。喧嘩屋のオレが\nまとめて買ってやるぜ！", 1, 106501, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (226, 0, "カヤ", "", "vo_empress_106501_002", 5, "vo_empress_106501_002", "", 1, "オレがドラゴン族なのも、\nこんな力を持ってるのも…きっと\n今日、この時のためだったんだ\nそうだろ？", 1, 106501, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (227, 0, "カヤ", "", "vo_empress_106501_003", 5, "vo_empress_106501_003", "", 1, "ウソだろ…オレが竦んじまってる…\nアイツのあの赤い眼から、眼を\nそらすんじゃねぇ…！　ドラゴン族\nのケンカ最強は…オレ様だろッ…！", 2, 106503, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (228, 106501, "カヤ", "", "vo_empress_106501_004", 5, "vo_empress_106501_004", "", 1, "自分の力に、ずっとビビッてた\nでも今は何よりこの力を頼もしく\n感じるぜ。テメェをぶっ倒し…\n明日を迎えるための力がなァ！", 3, 106501, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (229, 0, "イノリ", "", "vo_empress_106601_001", 5, "vo_empress_106601_001", "", 1, "どきやがれです！　最強ギャングが\nおまえのシマ分捕りにきたですよ！\nこんだけ仲間がいりゃ楽勝ですね♪\n尻尾巻いて逃げ出しやがれです！！", 1, 106603, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (230, 0, "イノリ", "", "vo_empress_106601_002", 5, "vo_empress_106601_002", "", 1, "あっちもゾロゾロつれてきやがり\nましたね…へんっ、このあたしが\nビビビビるとでもおお思うですか\n…お、お兄さん、どどどこです？", 1, 106601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (231, 0, "イノリ", "", "vo_empress_106601_003", 5, "vo_empress_106601_003", "", 1, "…！　あたしと同じドラゴン族？\nボスをプリンセスナイトに従えて\nたとか…へんっ、信じねーです！\nまあボスより性悪そ…ぴゃああっ", 2, 106603, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (232, 106601, "イノリ", "", "vo_empress_106601_004", 5, "vo_empress_106601_004", "", 1, "ふっふっふ～ん！　熱い力が\nどんどん溢れてくるですよっ！\nさあ、懲らしめてやるですっ！\nおしりペンペンですよ！", 3, 106602, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (233, 0, "ホマレ", "", "vo_empress_106701_001", 5, "vo_empress_106701_001", "", 1, "ふふっ、強そうな子がいっぱいだね\nそれじゃあ、誰が一番か決めよっか\nヴィーちゃんのプリンセスナイトで\n歴代最強は誰なのかを、ね♪", 1, 106701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (234, 0, "ホマレ", "", "vo_empress_106701_002", 5, "vo_empress_106701_002", "", 1, "ヴィーちゃんてば、そんな子たちと\n一緒にいるほうが楽しいんだ～？\nじゃ、私たちも見せつけないとだね\n遠慮なくやっちゃおう☆　あははっ", 1, 106701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (235, 0, "ホマレ", "", "vo_empress_106701_003", 5, "vo_empress_106701_003", "", 1, "これが、ヴィーちゃんの本気…\nとってもとってもすごいなぁ\n怖がりだからこそ、そんなに\n強くなれちゃったのかな…", 2, 106703, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (236, 106701, "ホマレ", "", "vo_empress_106701_004", 5, "vo_empress_106701_004", "", 1, "残念だけど、ヴィーちゃん…\nもうゲームオーバーみたいだよ\nあなたとのどんなゲームも私には…\n全部ドキドキして、楽しかったな", 3, 106702, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (237, 0, "ラビリスタ", "", "vo_empress_106801_001", 5, "vo_empress_106801_001", "", 1, "毎度、予想を超える困難ばかり\n押し寄せてくるんだからさ～\nま、アタシと少年が居る以上、\n好きにはさせないよ、ってね！", 1, 106802, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (238, 0, "ラビリスタ", 10000, "vo_empress_106801_002", 3, "vo_empress_106801_002", 1, 1, "よりによって真那まで相手かぁ…\nこりゃ一筋縄じゃいかなそうだ\n誰に対応するかは任せるけど、\n真那を相手取るなら頼ってよ", 4005, 106801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (239, 0, "ラビリスタ", "", "vo_empress_106801_003", 5, "vo_empress_106801_003", "", 1, "当然、奥の手も用意してくるよね\n次から次へと用意周到だこと…\nとはいえこっちも負けられない\nこの難局の突破口を探すとしよう！", 2, 106801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (240, 106801, "ラビリスタ", "", "vo_empress_106801_004", 5, "vo_empress_106801_004", "", 1, "七冠…しかも幻境竜后が相手なら\n手は抜けそうにもないね\nはは、でもアタシたちならきっと\n乗り越えられーる！　だよね少年♪", 3, 106802, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (241, 0, "ネネカ", 10000, "vo_empress_107001_001", 3, "vo_empress_107001_001", 1, 1, "真那…ふふ、こんなところで相対\nすることになるとは。いつぞやの\n借り、返してあげますよ。用意は\nいいですね？　マサキも、貴方も", 4005, 107001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (242, 0, "ネネカ", "", "vo_empress_107001_002", 5, "vo_empress_107001_002", "", 1, "数で私たちを圧倒しようなど…\n底の浅い戦略ですね。返り討ちに\nしてあげましょう…この世界を\nまだ失うわけにはいきませんから", 1, 107001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (243, 0, "ネネカ", "", "vo_empress_107001_003", 5, "vo_empress_107001_003", "", 1, "この力…計算外ではありますが\nそれは予想外という意味では\nありません。ええ、楽しみましょう\n不可能を解く、方程式の探求を", 2, 107001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (244, 107001, "ネネカ", "", "vo_empress_107001_004", 5, "vo_empress_107001_004", "", 1, "特等席で観察させてもらいましょう\n貴方の『心』という変数が\n『レジェンドオブアストルム』に\nどのような影響を与えるのかを…", 3, 107002, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (245, 0, "クリスティーナ", "", "vo_empress_107101_001", 5, "vo_empress_107101_001", "", 1, "クリスティーナさんのご登場だよ☆\nあっははは……☆　またとない宴だ\n心行くまで愉しもうじゃあないか\n血で血を洗うダンス…滾るな♪", 1, 107101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (246, 0, "クリスティーナ", 10000, "vo_empress_107101_002", 3, "vo_empress_107101_002", 1, 1, "真那さまがお出ましか…ワタシは\n本当に運がいいと見える♪　本気で\n刃を交える機会が巡ってくるなど\n願ってもない幸運だよ☆", 4005, 107101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (247, 0, "クリスティーナ", "", "vo_empress_107101_003", 5, "vo_empress_107101_003", "", 1, "…ここで退くなど興冷めだろう？\nたとえ足が竦んだとしても…退屈に\n食われるよりもよほどいい！\n最後まで愉しみつくしてやるさ…☆", 2, 107103, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (248, 107101, "クリスティーナ", "", "vo_empress_107101_004", 5, "vo_empress_107101_004", "", 1, "誤算だったなあ、『幻境竜后』\n他の者ならいざ知らず…\nキサマを殺せる唯一の力\n手にしたのはこの『誓約女君』だ！", 3, 107102, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (249, 0, "クロエ", "", "vo_empress_110801_001", 5, "vo_empress_110801_001", "", 1, "ざーす。世界を救う系の光バイトで\n来たんすけど…あ、説明とかは\n大丈夫っす。慣れてるんでノリで\n入れます─おのれ世界の敵め！", 1, 110801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (250, 0, "クロエ", 10000, "vo_empress_110801_002", 3, "vo_empress_110801_002", 1, 1, "なっつ、狐のねえさんいるじゃん\nまだ現役で悪モンやってたんだ\nてか中ボスポジに降格してるくね？\n世界の敵界隈、意外とせちがれーな", 4005, 110801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (251, 0, "クロエ", "", "vo_empress_110801_003", 5, "vo_empress_110801_003", "", 1, "なんかヤベーの出てきたな…\nこのカンジ、若干最悪っていうか\nぶっちゃけ流れ変わったくない？\nこっから捲るのは…結構ダルいわ", 2, 110803, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (252, 110801, "クロエ", "", "vo_empress_110801_004", 5, "vo_empress_110801_004", "", 1, "ちょ、聞いて敵、ウケんだけど\nなんかうち主人公だったみたいだわ\n山場でヒロインに力託され系のやつ\nてわけで、勝ち確いただきでーす", 3, 110802, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (253, 0, "チエル", "", "vo_empress_110901_001", 5, "vo_empress_110901_001", "", 1, "ちぇるーん☆　ボス敵のみんな～！\n初めまして＆お久しブリリアント！\n世界の美少女ちえるんでっす！\n今からぼっこぼこにしてあげるね！", 1, 110901, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (254, 0, "チエル", "", "vo_empress_110901_002", 5, "vo_empress_110901_002", "", 1, "クリスＰの敵はカルミナの敵！\nカルミナの敵はなかよし部の敵！\nツアー全通めざして戦います！\n現場の平和はチエルが守る！", 1, 110901, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (255, 0, "チエル", "", "vo_empress_110901_003", 5, "vo_empress_110901_003", "", 1, "あ、あのう…ヤバくないです？\n敵のねえさん、急に年末歌合戦の\nラスボス衣装みたくなりましたけど\nえ、どーしよ…揚げます白旗？", 2, 110903, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (256, 110901, "チエル", "", "vo_empress_110901_004", 5, "vo_empress_110901_004", "", 1, "世界の敵さん、ごめんちゃい！\nなんか愛だか絆だかの超理論的な\nアレでチエル覚醒しちゃいました！\nちぇるっと終わらせてあげますね！", 3, 110902, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (257, 0, "ユニ", "", "vo_empress_111001_001", 5, "vo_empress_111001_001", "", 1, "世界の危機だって？　何度目だね？\nざまあみろだよ、勝手に滅べば…\nなに、地球の危機？　この箱庭の\n話ではなく？　何ソレ一大事！", 1, 111001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (258, 0, "ユニ", "", "vo_empress_111001_002", 5, "vo_empress_111001_002", "", 1, "お、おい…敵が多すぎないか…？\n端の方でわちゃわちゃしてるだけの\n数合わせ要員として来たのだが…\nどういう事だ、聞いてた話と違うぞ", 1, 111001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (259, 0, "ユニ", "", "vo_empress_111001_003", 5, "vo_empress_111001_003", "", 1, "あばば…なんだ、あの奇怪な姿は…\nあれが理系をこじらせた者の末路か\n宇宙暗黒理系女…どうしてあんなに\nなるまで放っておいたんだ…", 2, 111003, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (260, 111001, "ユニ", "", "vo_empress_111001_004", 5, "vo_empress_111001_004", "", 1, "はん、驕ったな理系の女王よ\n世界は君が思うほど四角くない\n高機能計算機の弾いた数字ごときで\nぼくと彼の行間までは測れまいよ！", 3, 111002, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (261, 0, "クレジッタ", "", "vo_empress_118001_001", 5, "vo_empress_118001_001", "", 1, "ですからわたくしは商人で、\n戦いなどは不向き…などと\n言ってる場合ではありませんわね！\n参りますわよ、我が陛下のために！", 1, 118001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (262, 0, "クレジッタ", "", "vo_empress_118001_002", 5, "vo_empress_118001_002", "", 1, "ああもうはあもう、あっちこっち\n滅茶苦茶にしてくださってからに！\n復興費用の賠償はどなたに\n請求すればよろしいのかしら！？", 1, 118003, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (263, 0, "クレジッタ", "", "vo_empress_118001_003", 5, "vo_empress_118001_003", "", 1, "でっか！？　でっっっっか！！！\n幻境竜后でしたかしら！？\nなんなんですのあの高層建築な方、\n建築基準法違反ですわよ～っ！？", 2, 118003, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (264, 118001, "クレジッタ", "", "vo_empress_118001_004", 5, "vo_empress_118001_004", "", 1, "ホーッホッホッホ！　幻境竜后さん\n貴方にはいらっしゃるのかしら！\n利害でなくその理想のために\n命を賭ける、真実の忠臣が！", 3, 118002, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (265, 0, "ランファ", "", "vo_empress_118101_001", 5, "vo_empress_118101_001", "", 1, "恐ろしくて強そうな音が…たくさん\nでも…きっと、大丈夫。あなたや、\nミソラちゃん…みんなが一緒で…\nあたたかい音も、たくさんだもの…", 1, 118101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (266, 0, "ランファ", "", "vo_empress_118101_002", 5, "vo_empress_118101_002", "", 1, "緊張、してる…？　そ、それなら、\nわたしに、任せて…わたし、歌を、\n歌うわね…聴けばきっと、いつも\n通りの力を、出せると思うから…", 1, 118101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (267, 0, "ランファ", "", "vo_empress_118101_003", 5, "vo_empress_118101_003", "", 1, "お、音と声が、すごい…\nなんて…なんて恐ろしいのかしら…\n…？　で、でも…この音。\n幻境竜后も、恐怖…している…？", 2, 118103, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (268, 118101, "ランファ", "", "vo_empress_118101_004", 5, "vo_empress_118101_004", "", 1, "わたしの歌が、どれほど役立つかは\nわからない…そ、それでもっ、\nあなたの力になりたいの…だから\nわたし、精一杯、歌うわね…", 3, 118102, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (269, 0, "ミソラ", 10000, "vo_empress_118201_001", 3, "vo_empress_118201_001", 1, 1, "わー、ミロクさんや覇瞳皇帝さんも\nいるじゃないですか★\nそれじゃあわたしのガトリングで\nご挨拶といきましょっか♪", 4005, 118201, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (270, 0, "ミソラ", "", "vo_empress_118201_002", 5, "vo_empress_118201_002", "", 1, "騎士さんと力を合わせればどんな\n敵もほにゃららら～★　って感じで\nなんとかなると思うんですよねー\nほら、主人公補正ってやつで♪", 1, 118201, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (271, 0, "ミソラ", "", "vo_empress_118201_003", 5, "vo_empress_118201_003", "", 1, "復讐って、イイコトですかね？\n悪いコトですかね？まぁとりあえず\nぶっ壊してから考えましょうか\nね、幻境竜后さん─", 2, 118202, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (272, 118201, "ミソラ", "", "vo_empress_118201_004", 5, "vo_empress_118201_004", "", 1, "騎士さんに選んでもらっちゃいまし\nたし、いらない縁とはバイバイした\nいんですよねー♪　ってわけで、\nここで終わりにさせてもらいます★", 3, 118202, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (273, 0, "カリン", "", "vo_empress_118501_001", 5, "vo_empress_118501_001", "", 1, "みなさんの力を信じて、\n私も全力でサポートします\n連携と創意工夫があれば、きっと\nこの難局も乗り越えられます！", 1, 118501, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (274, 0, "カリン", "", "vo_empress_118501_002", 5, "vo_empress_118501_002", "", 1, "過去最大級の強敵が現れました！\nギルド管理協会を代表して…\nあなたに討伐を依頼します！\n報酬はお望みのままに、ですよ♪", 1, 118502, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (275, 0, "カリン", "", "vo_empress_118501_003", 5, "vo_empress_118501_003", "", 1, "…っ。さすがの強敵ですね…\nだからこそ、焦りは禁物…です\nあらゆる事態を想定して、ギルドの\nみなさんを支援するのが私の仕事…", 2, 118503, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (276, 118501, "カリン", "", "vo_empress_118501_004", 5, "vo_empress_118501_004", "", 1, "あなたと共に進めば\nどんな壁も越えられます\n私の、大切な人の無事を信じて…\n今こそ全力を尽くします！", 3, 118502, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (277, 0, "ネビア", "", "vo_empress_118601_001", 5, "vo_empress_118601_001", "", 1, "あんな奴らを野放しにしてたら\nこの世界が滅茶苦茶にされちゃう！\nでもまぁこれはこれでチャンスよ♪\n最っ高の悪戯の標的にしてあげる！", 1, 118601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (278, 0, "ネビア", "", "vo_empress_118601_002", 5, "vo_empress_118601_002", "", 1, "私はただのガイド妖精、みんなに\n比べれば大した力も持ってない…\nでも悪戯妖精なりの意地があんのよ\nあいつらに一泡吹かせてやるわ♪", 1, 118601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (279, 0, "ネビア", "", "vo_empress_118601_003", 5, "vo_empress_118601_003", "", 1, "幻境竜后、なんて力の持ち主なの\n正直きっついわ…でもまだやれる\n私はデータよ、壊れたって\nあんたを守る壁くらいにはなれる…", 2, 118603, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (280, 118601, "ネビア", "", "vo_empress_118601_004", 5, "vo_empress_118601_004", "", 1, "覚悟しなさいっ！\n出来損ないの悪戯妖精をなめたら\n痛い目に遭うって教えてあげる\nさぁ、最高のショーの始まりよ！", 3, 118602, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (281, 0, "ヴァンピィ", "", "vo_empress_122301_001", 5, "vo_empress_122301_001", "", 1, "むー！　いたずらっこの暴れんぼ\nさんたちは、ヴァンピィちゃんが\nきつーくおしおきしちゃうよ！\n真祖のおつとめですから！", 1, 122303, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (282, 0, "ヴァンピィ", "", "vo_empress_122301_002", 5, "vo_empress_122301_002", "", 1, "けんぞくはヴァンピィちゃんの\n背中に隠れてなさいっ。え？\n背中を守りたい？　うん、それなら\nよろしい！　一緒だよ、けんぞく！", 1, 122302, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (283, 0, "ヴァンピィ", "", "vo_empress_122301_003", 5, "vo_empress_122301_003", "", 1, "幻境竜后？　ふーんだ！\nベスちゃんのほーが、ずーっと\n強くてカッコいいですし！\nいくよっ、けんぞくぅ！", 2, 122303, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (284, 122301, "ヴァンピィ", "", "vo_empress_122301_004", 5, "vo_empress_122301_004", "", 1, "ここはみんなの『いばしょ』！\n壊しちゃうなんて、許さないもん\nヴァンピィちゃん、本気で怒ったよ\nやっちゃうよ、けんぞく！", 3, 122302, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (285, 0, "アメス", "", "vo_empress_123001_001", 5, "vo_empress_123001_001", "", 1, "ほら、あんたは余計な心配しないの\nあいつらに好き勝手させないように\n全力でぶつかっていくだけよ\nあたしたちの未来のためにね♪", 1, 123002, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (286, 0, "アメス", "", "vo_empress_123001_002", 5, "vo_empress_123001_002", "", 1, "…あの連中も強くてやばいけど…\n一番やばいのは、こんなにたくさん\n女の子の知り合いがいる\nあんたかもしれないわね…", 1, 123001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (287, 0, "アメス", "", "vo_empress_123001_003", 5, "vo_empress_123001_003", "", 1, "なんて相手なの…さすがに想定を\n超えてるわよ…こんなの卑怯よね\nだからってここで逃げやしないわよ\nせめて、あんたを守るくらいは…！", 2, 123003, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (288, 123001, "アメス", "", "vo_empress_123001_004", 5, "vo_empress_123001_004", "", 1, "敵がどれだけ強くたって関係ないわ\nあんたの行く道はあたしが照らす\n迷ったらあたしを見なさい\nどこまでだって導いてあげる！", 3, 123002, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (289, 0, "ネア", "", "vo_empress_123301_001", 5, "vo_empress_123301_001", "", 1, "『レギオンウォー』思い出すな～\nあん時は敵側だったけどー\n今回は騎士きゅんたちの隣で\nネアおねえちゃんもがんばるぞ～♡", 1, 123301, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (290, 0, "ネア", "", "vo_empress_123301_002", 5, "vo_empress_123301_002", "", 1, "だる～、激ヤバなテキばっかじゃん\n騎士きゅんパワー充電しねーと\nおねえちゃんもギリギリかもー\nとりま、ちゅっちゅ♡　してい？", 1, 123301, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (291, 0, "ネア", "", "vo_empress_123301_003", 5, "vo_empress_123301_003", "", 1, "激ヤバドラゴン、ガチしんどー…\nま、だからって負ける気ねーけど\nこーゆう時こそ、スライムの\n粘り強さの見せ所っしょ～　ね♪", 2, 123303, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (292, 123301, "ネア", "", "vo_empress_123301_004", 5, "vo_empress_123301_004", "", 1, "ンフフフフ～♪　今のアタシ、\n騎士きゅんと一心同体ってやつ～？\nめちゃめちゃアガるわ～♪\n愛の力パねぇ～♡", 3, 123302, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (293, 0, "クローチェ", "", "vo_empress_126401_001", 5, "vo_empress_126401_001", "", 1, "ビーッ！　ビーッ！\nあっちもこっちもそっちも\n強そうな人たちでいっぱいですっ！\nセンサーが壊れちゃいそう～っ！", 1, 126401, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (294, 0, "クローチェ", "", "vo_empress_126401_002", 5, "vo_empress_126401_002", "", 1, "世界が大変なことになってますっ！\nでもわたしたちは今までだって、\n大変な戦いを乗り越えてきましたっ\nきっと…ううん、絶対勝てますっ！", 1, 126401, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (295, 0, "クローチェ", "", "vo_empress_126401_003", 5, "vo_empress_126401_003", "", 1, "ビビービビビーッ！　…ひゃあっ！\nセンサーが壊れちゃいました…！\nしかも、照準が震えちゃって…\n…これが…この感情が、恐怖…？", 2, 126403, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (296, 126401, "クローチェ", "", "vo_empress_126401_004", 5, "vo_empress_126401_004", "", 1, "今のわたしたちに、怖いものなんて\nありませんっ！　敵さんがどんなに\n強くても…わたしとナイトさんの\n特別なパワーは、もっと強いです！", 3, 126402, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (297, 0, "ライラエル", "", "vo_empress_126501_001", 5, "vo_empress_126501_001", "", 1, "ジオ・テオゴニアの姫として\nこの星に生きる一個として\nこれ以上の蹂躙を許すわけには\nいきません。そうですね？　騎士", 1, 126501, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (298, 0, "ライラエル", 10000, "vo_empress_126501_002", 3, "vo_empress_126501_002", 1, 1, "穢らわしい、色狂いの山羊めが\n我が従僕を傀儡としてくれた借り、\n兆倍──否、京倍にして\n返してくれようぞ。崩雷夜天！", 4002, 126506, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (299, 0, "ライラエル", "", "vo_empress_126501_003", 5, "vo_empress_126501_003", "", 1, "幻境竜后。迷いなく、圧倒的な力で\nわたしたちの調和を滅しようとする\nそんな力を、認めたくはないのに…\nなんて、困難な戦いなのでしょう…", 2, 126503, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (300, 126501, "ライラエル", "", "vo_empress_126501_004", 5, "vo_empress_126501_004", "", 1, "この星には、あなたがいる…\n悪辣な侵略者と戦う理由など、\nただそれだけで十分です\n守りましょう。わたしたちの世界を", 3, 126502, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (301, 0, "リンド", 10000, "vo_empress_127701_001", 3, "vo_empress_127701_001", 1, 1, "あそこにヴルムを傷つけた人が…！\n…騎士さん、絶対勝ちましょうね\nあの人たちのやったこと、私\n絶対ぜったい許しませんから！", 4002, 127701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (302, 0, "リンド", "", "vo_empress_127701_002", 5, "vo_empress_127701_002", "", 1, "騎士さんたちと出会えたこの世界を\n悪いことになんか使わせません\n作り物だなんて信じられませんけど\n失っちゃいけないものはわかります", 1, 127701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (303, 0, "リンド", "", "vo_empress_127701_003", 5, "vo_empress_127701_003", "", 1, "まだこんな力が残ってるの…！？\n考えなきゃ、私にできること…\n何か…何かないの…！？\nまた私、何もできないの…？", 2, 127703, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (304, 127701, "リンド", "", "vo_empress_127701_004", 5, "vo_empress_127701_004", "", 1, "あなたが側にいてくれるから、\n私もこうして戦えます\nチョロいって言われてもいいです\n私にとって、大切なひとですから", 3, 127702, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (305, 0, "ヴルム", "", "vo_empress_127801_001", 5, "vo_empress_127801_001", "", 1, "…正直、サボりとかじゃなくて…\nぜんぜん身体はきついです。でも…\n姉貴やみんなと過ごすこの世界は\n誰にも壊させやしませんから…！", 1, 127801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (306, 0, "ヴルム", 10000, "vo_empress_127801_002", 3, "vo_empress_127801_002", 1, 1, "騎士さん…アルシャトのこと\nあたしにも一発殴らせてください\nふざけた真似してくれたお礼…\n倍にして返してやりますよ", 4002, 127801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (307, 0, "ヴルム", "", "vo_empress_127801_003", 5, "vo_empress_127801_003", "", 1, "冗談きついです、こんなの…\n勝てっこないじゃないですか\nあたしだってドラゴン族なのに\nこれほどまでに差があるだなんて…", 2, 127803, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (308, 127801, "ヴルム", "", "vo_empress_127801_004", 5, "vo_empress_127801_004", "", 1, "もう後先考えずにいきますよ\n面倒見てくれる人がここにいるので\nあたしと騎士さんが揃えば\n無敵だってとこ見せてやります", 3, 127802, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (309, 0, "エリス", 10000, "vo_empress_129001_001", 3, "vo_empress_129001_001", 1, 1, "覇瞳皇帝…わたしの邪魔をするなら\nかつてのように、消去するだけ\nミロクも…わたしを草野優衣の\n複製と呼んだこと、後悔させてやる", 4005, 129001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (310, 0, "エリス", "", "vo_empress_129001_002", 5, "vo_empress_129001_002", "", 1, "管理者の座は失っても\nわたしの意志は揺らがない…\n騎士クンの物語を紡ぐために…\nそれが、わたしの全てだから", 1, 129001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (311, 0, "エリス", "", "vo_empress_129001_003", 5, "vo_empress_129001_003", "", 1, "これが七冠、幻境竜后の全力…\n管理者だったかつてのわたしを、\n超えるほどの脅威…でも、\n騎士クンだけは、守ってみせる…", 2, 129003, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (312, 129001, "エリス", "", "vo_empress_129001_004", 5, "vo_empress_129001_004", "", 1, "孤独も絶望も越えてきた\nもうどんな闇にも迷わない\n騎士クンが隣にいる限り\nわたしは、負けない", 3, 129002, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (313, 0, "アネモネ", "", "vo_empress_129601_001", 5, "vo_empress_129601_001", "", 1, "リアを──媛を、傷つけたひとたち\n笑ってられるのも今だけです──\nアルラウネの棘の鋭さ、\n教えてあげますから──", 1, 129601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (314, 0, "アネモネ", "", "vo_empress_129601_002", 5, "vo_empress_129601_002", "", 1, "騎士のひと──背中は、任せます\n貴方のこと、\n媛と同じくらい、信じてるので──\n自分でも、びっくりですけど", 1, 129601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (315, 0, "アネモネ", "", "vo_empress_129601_003", 5, "vo_empress_129601_003", "", 1, "私、ずっと抗ってきたんです\nそのために、強くなったはず──\nだから──諦めたく、ないです…", 2, 129603, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (316, 129601, "アネモネ", "", "vo_empress_129601_004", 5, "vo_empress_129601_004", "", 1, "体が熱くて、思考がまとまらなくて\nなのに負ける気がしない──なんて\nよくわからないです。どうしてか、\n後で教えてください──騎士のひと", 3, 129601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (317, 0, "ネフィ＝ネラ", "", "vo_empress_129701_001", 5, "vo_empress_129701_001", "", 1, "難敵強敵揃い踏みなれど\nわっちらが退く理はありんせん\n騎士殿や、手を携えて此度の争乱\n鎮めて見せましょう也", 1, 129701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (318, 0, "ネフィ＝ネラ", "", "vo_empress_129701_002", 5, "vo_empress_129701_002", "", 1, "今のわっちが萎弱であろうとて\n貴様等如き梟悪に斃される訳には\nゆかぬ也。再び足甲を舐めさせ\n地に臥すまで仕置きを致しんしょう", 1, 129701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (319, 0, "ネフィ＝ネラ", "", "vo_empress_129701_003", 5, "vo_empress_129701_003", "", 1, "我が矜持『不退転』─如何なる敵で\nあろうとも揺らぐ仕儀はなし。斯様\nな邪竜程度、退けむと思い侍りしが\n─難儀な由、残念至極─…", 2, 129703, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (320, 129701, "ネフィ＝ネラ", "", "vo_empress_129701_004", 5, "vo_empress_129701_004", "", 1, "参りまする也、騎士殿や\n懼るること等何一つ御座りんせん\n唯わっちらの勇儀を以て、此の星の\n明日を再び…掌中に致しんしょう", 3, 129702, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (321, 0, "ヤマト", 10000, "vo_empress_130001_001", 3, "vo_empress_130001_001", 1, 1, "─おや、フレイヤじゃないか\nずいぶん様変わりしたようだが\n今の方がアタシとしちゃ好みだね\nお礼参りのしがいもあるってもんさ", 4003, 130001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (322, 0, "ヤマト", "", "vo_empress_130001_002", 5, "vo_empress_130001_002", "", 1, "…フゥン？　あっちもこっちも\n『王家の装備』を持ってるらしいね\n宝の山ってのはこのことかい\nまとめて搔っ攫ってやろうかね…！", 1, 130001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (323, 0, "ヤマト", "", "vo_empress_130001_003", 5, "vo_empress_130001_003", "", 1, "ちっ…、幻境竜后つったかい\n世界を奪おうってのも冗談じゃ\nなさそうだ。…ワカナ、フブキ…\nお前たちだけでも、逃げな…", 2, 130003, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (324, 130001, "ヤマト", "", "vo_empress_130001_004", 5, "vo_empress_130001_004", "", 1, "アタシらの住み家を奪おうだぁ？\nハッ、笑わせてくれるね\n盗賊は盗むモンであって、\n盗まれるモンじゃあないンだよ！", 3, 130002, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (325, 0, "ワカナ", "", "vo_empress_130101_001", 5, "vo_empress_130101_001", "", 1, "つ、強そうな人たちがたくさん…\nなのに姉さんもフブキちゃんも\nやる気満々だし…\nわたし、どうすればいいのぉ～っ", 1, 130101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (326, 0, "ワカナ", "", "vo_empress_130101_002", 5, "vo_empress_130101_002", "", 1, "きっと、長期戦になりますよね…\nあ、あの…ご飯、食べませんか？\nお腹が空くといけないと思って、\n作ってきたので…よろしければっ", 1, 130101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (327, 0, "ワカナ", "", "vo_empress_130101_003", 5, "vo_empress_130101_003", "", 1, "む…むりっ！　無理ですよ～っ！\nあんなおっきいドラゴンなんて、\n勝てるわけないじゃないですかっ\nに、逃げちゃいましょ、ねっ…！？", 2, 130103, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (328, 130101, "ワカナ", "", "vo_empress_130101_004", 5, "vo_empress_130101_004", "", 1, "と、盗られるぐらいなら盗るのが\n【バンディ・シスターズ】流ですっ\n騎士さん、わたしたちの未来を\n掴み取りにいきましょう…っ！", 3, 130102, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (329, 0, "フブキ", "", "vo_empress_130201_001", 5, "vo_empress_130201_001", "", 1, "だる～、ささっと片付けてきてよ～\nムリ？　知ってる～だってザコザコ\nお兄さんだもんね♪　しょーがない\n助けてあげよっかな～？きゃはは♡", 1, 130201, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (330, 0, "フブキ", "", "vo_empress_130201_002", 5, "vo_empress_130201_002", "", 1, "あの陰気ダサダサメガネさー、\n仲間集めてチョーシ乗ってねー？\nザコは何匹集まったってザコだって\nフブキちゃんが教えてあげまーす♪", 1, 130201, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (331, 0, "フブキ", "", "vo_empress_130201_003", 5, "vo_empress_130201_003", "", 1, "ふぇぇ…まじムリ、アイツムリ～！\n全然ラスボスってカンジじゃん！？\nぼくお家かえるぅ～っ！\nお兄さんも一緒にかえろっ、ねっ？", 2, 130203, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (332, 130201, "フブキ", "", "vo_empress_130201_004", 5, "vo_empress_130201_004", "", 1, "お兄さん、やる気漲っちゃってる？\nだよねー、世界が滅んじゃったら\nぼくとも永遠のお別れなんだし？\n必死になるのもトーゼンっしょ～♡", 3, 130202, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (333, 0, "クルル", "", "vo_empress_130901_001", 5, "vo_empress_130901_001", "", 1, "はわっ！？　すっごくすっごく\n悪そうな人達いっぱいですますぅ！\nかばばん君、警備員モードです！\nぴっぴーーーー！", 1, 130901, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (334, 0, "クルル", "", "vo_empress_130901_002", 5, "vo_empress_130901_002", "", 1, "この戦いが終わったら、みなさんと\nパークで凱旋パレードですぅ♪\n…ふぇっ？\n気が早いですますか？", 1, 130901, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (335, 0, "クルル", "", "vo_empress_130901_003", 5, "vo_empress_130901_003", "", 1, "はわわっ！　幻境竜后さん、\n強そうすぎですっ…でもっ！\nやっと再建したパークも世界も\nぜったい壊させないですよ～っ！", 2, 130903, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (336, 130901, "クルル", "", "vo_empress_130901_004", 5, "vo_empress_130901_004", "", 1, "ヒーローさんのこと、\nクルルの全部でお助けしますです！\nジオ・テオゴニアでも、どんな世界\nでも…ずっと、ず～っとですっ！", 3, 130902, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (337, 0, "ルイズマリー", "", "vo_empress_132301_001", 5, "vo_empress_132301_001", "", 1, "なっなんなのよこいつらっ！\nダーリンとの恋路を邪魔する気…？\nそんなことさせないわ…だって、\n二人の恋はエターナルですからっ！", 1, 132301, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (338, 0, "ルイズマリー", "", "vo_empress_132301_002", 5, "vo_empress_132301_002", "", 1, "愛情×愛情＝無限大…\n遂に錬金術の神髄に辿り着いたわ…\nさあ…お見舞いしてやりましょう！\n私とダーリンの究極錬成をっ！", 1, 132301, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (339, 0, "ルイズマリー", "", "vo_empress_132301_003", 5, "vo_empress_132301_003", "", 1, "あ、あなたがどんなに強くても、\n私は逃げないわ！　ダーリンに\nちょっかいかける奴は絶対に\n許さないって決めてるから…っ！！", 2, 132303, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (340, 132301, "ルイズマリー", "", "vo_empress_132301_004", 5, "vo_empress_132301_004", "", 1, "悪いけど速攻で終わらせちゃうわ！\n早く帰ってダーリンと心行くまで\n破廉恥な乳繰り合い…じゃなくて！\n愛を確かめ合うんだからっ！", 3, 132302, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (341, 0, "イロハ", "", "vo_empress_132401_001", 5, "vo_empress_132401_001", "", 1, "わわっ、敵がいっぱい！\nこれがクワガタだったら最高…よし\n新種のクワガタって事にしちゃお！\nあははっ！　待て待て～っ！！", 1, 132401, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (342, 0, "イロハ", "", "vo_empress_132401_002", 5, "vo_empress_132401_002", "", 1, "あはは、まだまだ出てくるね～！\nなら新しい技いっぱい\n試しちゃおっか…さあ、いくよ！\n──イスルギ流奥義っ！！", 1, 132401, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (343, 0, "イロハ", "", "vo_empress_132401_003", 5, "vo_empress_132401_003", "", 1, "あのおねーさんもなかなか良いツノ\n持ってるねえ♪　イロハが勝ったら\nルイちゃんと二人でクワガタ相撲\nごっこやってもらおっと！", 2, 132401, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (344, 132401, "イロハ", "", "vo_empress_132401_004", 5, "vo_empress_132401_004", "", 1, "おねーさんがどんなに強くたって\nイロハは絶対に負けない！\nおじちゃんが見ててくれてる時の\nイロハは、サイキョーなんだから！", 3, 132402, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (345, 0, "ソノ", "", "vo_empress_132501_001", 5, "vo_empress_132501_001", "", 1, "いや無理無理、戦いとか苦手過ぎる\n…でも君となら、奇跡起こせるかも\n…うわやば、今の忘れて\n若者みたいなこと言っちゃったよ…", 1, 132501, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (346, 0, "ソノ", "", "vo_empress_132501_002", 5, "vo_empress_132501_002", "", 1, "敵、まだいっぱいいるじゃん…\nはあ…残業したくないけど頑張るか\n全部終わったら君からのマッサージ\n期待しとくから、ね", 1, 132501, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (347, 0, "ソノ", "", "vo_empress_132501_003", 5, "vo_empress_132501_003", "", 1, "はあ…はあ…幻境竜后だっけ？\nルイちゃんの錬金術より\n出鱈目な強さだね…！\nでもまだまだ諦めない…いくよ！", 2, 132503, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (348, 132501, "ソノ", "", "vo_empress_132501_004", 5, "vo_empress_132501_004", "", 1, "こんなに強い敵が相手でも\n諦めなきゃ勝てるんだって\n教えてくれたのは君だよ\nふふ…ありがとね、若者♪", 3, 132502, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (349, 0, "グレイス", "", "vo_empress_133001_001", 5, "vo_empress_133001_001", "", 1, "うーわ。あっちもこっちも\nボス級だらけじゃないですか\nま、ヴァイオレット姫には\n指一本触れさせませんけどね", 1, 133001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (350, 0, "グレイス", 10000, "vo_empress_133001_002", 3, "vo_empress_133001_002", 1, 1, "リーザ…今度こそ、決着の時ね\nいくら頭数を揃えても私は…いえ\n私と騎士氏は絶対に負けないわ\nこの槍で、冥界に送り返してあげる", 4001, 133003, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (351, 0, "グレイス", "", "vo_empress_133001_003", 5, "vo_empress_133001_003", "", 1, "ぐっ…圧倒的ですね『幻境竜后』\nですが…決してあきらめません\n私には、生きていてほしい人が\nたくさんいますので…！", 2, 133003, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (352, 133001, "グレイス", "", "vo_empress_133001_004", 5, "vo_empress_133001_004", "", 1, "とてつもない強敵を前にしてるのに\nまるで恐怖心を感じません…\n…恋とは、心霊現象よりも\n不思議なものらしいですよ", 3, 133002, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (353, 0, "ヴァイオレット", "", "vo_empress_133101_001", 5, "vo_empress_133101_001", "", 1, "恐るべき方々ばかりです…\nですがわたくしは絶対に退きません\nジオ・ニヴルヘルの姫として\nこの世界を守ると決めたのです！", 1, 133101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (354, 0, "ヴァイオレット", 10000, "vo_empress_133101_002", 3, "vo_empress_133101_002", 1, 1, "リーザ…どうしてもわたくしたちの\n前に立ちはだかるというのですね\nならばわたくしも覚悟を決めました\nこの手であなたを、倒します…！", 4001, 133101, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (355, 0, "ヴァイオレット", "", "vo_empress_133101_003", 5, "vo_empress_133101_003", "", 1, "これが、彼女の本気の力…！\n異質で…故に、とても寂しい…\n本当の意味で彼女に届く声が、\nこの世界に存在するのでしょうか…", 2, 133103, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (356, 133101, "ヴァイオレット", "", "vo_empress_133101_004", 5, "vo_empress_133101_004", "", 1, "あなたとの「繋がり」がある限り\n死が牙を剥くことはありません\n手を取り合い、共に参りましょう\nわたくしたちの未来のために！", 3, 133102, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (357, 0, "メドゥーサ", "", "vo_empress_133601_001", 5, "vo_empress_133601_001", "", 1, "フンっ、次から次へと…！　なら\n思う存分、大暴れしてやるから♪\nやっちゃうわよ、メドゥシアナ！\nアンタも！！", 1, 133601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (358, 0, "メドゥーサ", "", "vo_empress_133601_002", 5, "vo_empress_133601_002", "", 1, "どこの誰だか知らないけれど、\nアタシの魔眼でまとめて石に…って\nきゃああああ！　こんなバケモン級\nなら先に教えときなさいよ～っ！", 1, 133601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (359, 0, "メドゥーサ", "", "vo_empress_133601_003", 5, "vo_empress_133601_003", "", 1, "な…なんなの、アイツの『眼』…\nでもねっ、アタシはメドゥーサ\nゴルゴーンの、お姉ちゃんの妹よ！\n睨みあいで負けるわけがないわ！", 2, 133603, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (360, 133601, "メドゥーサ", "", "vo_empress_133601_004", 5, "vo_empress_133601_004", "", 1, "知ってる？　蛇って執念深いのよ\nこの『眼』で見つけてやったわ\n幻境竜后、アンタが一番恐れること\nアタシとこいつが手をつなぐこと！", 3, 133602, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (361, 0, "ホウオウ", "", "vo_empress_134701_001", 5, "vo_empress_134701_001", "", 1, "この大地と大空を守るため、\n人の子らだけに任せてはおけません\n鳳凰のはばたきで、その野望ごと\n跡形もなく吹き飛ばしましょう！", 1, 134701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (362, 0, "ホウオウ", "", "vo_empress_134701_002", 5, "vo_empress_134701_002", "", 1, "さあ皆さん、ここが正念場です！\n私がいれば楽勝圧勝間違いなし！\n…えっ？　私が先頭？　えーと…\nあっちょっと待って押さないで！", 1, 134701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (363, 0, "ホウオウ", "", "vo_empress_134701_003", 5, "vo_empress_134701_003", "", 1, "羽が散って、ちっ、力が…\n幻境竜后、やるではないですか…\nしかし、私も不死鳥と呼ばれた身…\nただでやられは…ぴ、ぴよぉぉ～…", 2, 134703, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (364, 134701, "ホウオウ", "", "vo_empress_134701_004", 5, "vo_empress_134701_004", "", 1, "幻境竜后、でしたか？\nあなたも運のない方ですね\n今の私は輪廻史上最強の鳳凰\nその鱗一つ残さず焼き尽くします！", 3, 134702, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (365, 0, "カノン", "", "vo_empress_134901_001", 5, "vo_empress_134901_001", "", 1, "ヲ～ッホッホ！　どいつもこいつも\n大層なおツラ構えしてますけどぉ？\nあたくし様の敵じゃありませんわ！\nほら馬ボーン！　お強化なさいな！", 1, 134901, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (366, 0, "カノン", "", "vo_empress_134901_002", 5, "vo_empress_134901_002", "", 1, "いってぇ～ですわ！　あたくし様の\nお美しいお肌を傷つけましたわね！\nまとめてお成敗して差し上げますわ\nついてらっしゃいな！　馬ボーン！", 1, 134901, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (367, 0, "カノン", "", "vo_empress_134901_003", 5, "vo_empress_134901_003", "", 1, "なんてタマですの…アースハイドラ\nよりデカいなんて聞いてませんわ！\nでも…ここでお尻尾巻いて逃げる\nなら、死んだ方がマシですわ…！", 2, 134903, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (368, 134901, "カノン", "", "vo_empress_134901_004", 5, "vo_empress_134901_004", "", 1, "幻境竜后とやら、お覚悟なさいな\nあたくしと馬ボーンの前に立つなど\n100億万年お早いですわ！\n華麗にお成敗して差し上げますわ♪", 3, 134902, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (369, 0, "アイラ", "", "vo_empress_135501_001", 5, "vo_empress_135501_001", "", 1, "来たね、お姉さんの出番ってやつ♪\nキミと一緒に戦えるなんて、あたし\nテンション最高潮だよ！　あははっ\nさ、思いっきり暴れちゃおっか！", 1, 135501, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (370, 0, "アイラ", 10000, "vo_empress_135501_002", 3, "vo_empress_135501_002", 1, 1, "あれが…覇瞳皇帝のオリジナルだね\nま、関係ないや。本物でも偽物でも\n今度こそ決着つけてあげるから！\nお姉さんの拳…燃え盛ってるよー！", 4005, 135501, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (371, 0, "アイラ", "", "vo_empress_135501_003", 5, "vo_empress_135501_003", "", 1, "幻境竜后…とんでもない相手だね\nあたしの拳だって届かないかも…\nそれでも、燃え尽きるまで戦うよ\nキミが信じてくれてる限り、ね！", 2, 135503, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (372, 135501, "アイラ", "", "vo_empress_135501_004", 5, "vo_empress_135501_004", "", 1, "キミがいれば怖いものなし！\nお姉さん今、燃えに燃えてるよっ\n太陽より熱く燃える拳で…\n全部まとめてぶっ飛ばす！", 3, 135502, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (373, 0, "シナツ", "", "vo_empress_135601_001", 5, "vo_empress_135601_001", "", 1, "どれほどの逆風の中にいても、\n諦めてはならない…そうだろう？\nかつて私が、他でもないキミたちに\nそう教えてもらったんだ…", 1, 135601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (374, 0, "シナツ", "", "vo_empress_135601_002", 5, "vo_empress_135601_002", "", 1, "私はこの世界の人々と出会い、\n失ったはずの希望を見つけられた\n今度は私が、皆に希望を届ける番だ\nこの刃、存分に振るわせてくれ", 1, 135601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (375, 0, "シナツ", "", "vo_empress_135601_003", 5, "vo_empress_135601_003", "", 1, "幻境竜后…私たちの世界を創造し、\nそして滅ぼそうとした張本人か…！\nその力がどんなに強大だとしても…\n私は…絶対に逃げたりなどしない！", 2, 135603, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (376, 135601, "シナツ", "", "vo_empress_135601_004", 5, "vo_empress_135601_004", "", 1, "私の刃に、もはや一片の曇りもない\n皆と生きる未来を守り抜くために\n戦いつづける…ただそれだけだ\n─道を阻む者は全て斬り伏せる！", 3, 135602, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (377, 0, "ユキノ", 10000, "vo_empress_135801_001", 3, "vo_empress_135801_001", 1, 1, "リ、リ、リーザちゃ…！\nリーザちゃはあてのこと、ヘタレの\nホジナシって思ってっかもだけど…\n前より成長したとこ、見せっから！", 4001, 135801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (378, 0, "ユキノ", "", "vo_empress_135801_002", 5, "vo_empress_135801_002", "", 1, "田舎者で世間知らずなあてだけど…\n騎士さと一緒にいろんなとこ行って\n大切な思い出、いっぱいできたよ…\nだから守りてぇんだ、この世界…！", 1, 135801, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (379, 0, "ユキノ", "", "vo_empress_135801_003", 5, "vo_empress_135801_003", "", 1, "あ、あても、ちったぁでけぇけど…\n幻境竜后、で、でっかすぎ…！\nそ、それに竜まで…！　炎浴びたら\nあて、溶けちまうよぅ…！", 2, 135803, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (380, 135801, "ユキノ", "", "vo_empress_135801_004", 5, "vo_empress_135801_004", "", 1, "「あてなんか」なんて、考えね…\n騎士さが信じてくれるなら、\nあてだって自分のこと、信じるよ\nあてと騎士さなら大丈夫、って…！", 3, 135802, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (381, 0, "サツキ", 10000, "vo_empress_135901_001", 3, "vo_empress_135901_001", 1, 1, "リザ公…手前ェどの面下げて\n俺の前に出てきやがった\nまァいいさ、何聞いても今更だ\nここで落とし前つけてもらうぜ", 4001, 135903, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (382, 0, "サツキ", "", "vo_empress_135901_002", 5, "vo_empress_135901_002", "", 1, "いつ死んでもいいなんて\nもう思っちゃいねぇさ\nこの悪玉どもより、図太くしぶとく\n生き抜いてやろうじゃねぇか", 1, 135901, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (383, 0, "サツキ", "", "vo_empress_135901_003", 5, "vo_empress_135901_003", "", 1, "あれが幻境竜后か…\nハンパじゃねェや\nしゃあねぇ、こうなりゃ一丁\n死に花咲かすとするか", 2, 135901, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (384, 135901, "サツキ", "", "vo_empress_135901_004", 5, "vo_empress_135901_004", "", 1, "世界だの未来だの現実だの…\n重いったらありゃしねぇぜ\n潰れるなよ、騎士公\n俺も一緒に担いでやっからさ", 3, 135902, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (385, 0, "アラクネ", "", "vo_empress_136001_001", 5, "vo_empress_136001_001", "", 1, "騎士さま、どうかご安心を…\nどれだけ厳しい運命が待って\nいたとしても…あなたのことは、\nわたしの糸が必ずお守りします", 1, 136001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (386, 0, "アラクネ", 10000, "vo_empress_136001_002", 3, "vo_empress_136001_002", 1, 1, "…？　あの金髪の女性、なんだか\n見覚えあるような気が…いえ\n騎士さまの敵は、わたしの敵です\nそれだけです…", 4003, 136001, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (387, 0, "アラクネ", "", "vo_empress_136001_003", 5, "vo_empress_136001_003", "", 1, "あれが幻境竜后さま…\nなんという恐るべき力\n…騎士さま、わたしの後ろに\n一度くらいは、庇えるはずです…", 2, 136003, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (388, 136001, "アラクネ", "", "vo_empress_136001_004", 5, "vo_empress_136001_004", "", 1, "騎士さまという光が、わたしに力を\n与えてくれるのです。ともに未来を\n歩むためにも…この戦いに\n必ず勝ちましょう、騎士さま", 3, 136002, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (389, 0, "ナーナ", "", "vo_empress_136201_001", 5, "vo_empress_136201_001", "", 1, "強そうな敵さんがいっぱい～っ！？\nこーなったら、ウルトラとっておき\nドーナツ！　ちょっと湿気てるけど\n…はい騎士ちゃん、あーんっ♪", 1, 136201, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (390, 0, "ナーナ", "", "vo_empress_136201_002", 5, "vo_empress_136201_002", "", 1, "ナーナだって頑張れるんだよっ！\n騎士ちゃんに、そう教わったもん！\nだから、すごく怖いけど…でもっ…\nナーナ、逃げたりしないよぉっ！", 1, 136201, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (391, 0, "ナーナ", "", "vo_empress_136201_003", 5, "vo_empress_136201_003", "", 1, "うぅ…あ、足が震えてきちゃった…\nでも動かなきゃ、戦わなきゃっ…\nわかってるのに、でもでもぉ…\nうえぇぇん、やっぱり怖いぃぃ！", 2, 136201, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (392, 136201, "ナーナ", "", "vo_empress_136201_004", 5, "vo_empress_136201_004", "", 1, "今のナーナはよわよわウサギじゃ\nないんだよ。騎士ちゃんのためなら\nどんな敵さんだってやっつけちゃう\nつよつよウサギなんだから！", 3, 136202, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (393, 0, "ルルィ", 10000, "vo_empress_136901_001", 3, "vo_empress_136901_001", 1, 1, "リーザ姉しゃまが裏切ったなんて\nあたち、信じたくないでしゅ…！\nだから直接聞きにいきましゅ\n吸盤ぜんぶで捕まえてでも…！", 4001, 136903, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (394, 0, "ルルィ", "", "vo_empress_136901_002", 5, "vo_empress_136901_002", "", 1, "姫姉しゃまも騎士しゃんも\nみなしゃん戦ってるんでしゅ\nあたちだって負けましぇん！\n一生懸命がんばりましゅ～！", 1, 136901, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (395, 0, "ルルィ", "", "vo_empress_136901_003", 5, "vo_empress_136901_003", "", 1, "あ、あの方、こわいでしゅ…！\n丸呑みにされちゃいそうでしゅっ\nうじゅ…がんばりたいでしゅが…\n震えが止まらないでしゅ…！", 2, 136903, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (396, 136901, "ルルィ", "", "vo_empress_136901_004", 5, "vo_empress_136901_004", "", 1, "あたちは強くないでしゅけど\n騎士しゃんとの約束がありましゅ\nだから誰にも負けましぇん！\nいっちょに、守りましゅよ！", 3, 136902, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (397, 0, "リリ", "", "vo_empress_139501_001", 5, "vo_empress_139501_001", "", 1, "これから挑む敵がどれだけ強いと\nしても、勇往邁進していきます\nですからこの戦いでも、兄様の\nおそばで戦わせてくださいませ", 1, 139501, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (398, 0, "リリ", 10000, "vo_empress_139501_002", 3, "vo_empress_139501_002", 1, 1, "幻境竜后の手先、アルシャト…！\nリアさんやヴルム様を陥れた貴方を\n決して許す訳には参りません！\n不倶戴天─ここで成敗致します！", 4002, 139503, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (399, 0, "リリ", "", "vo_empress_139501_003", 5, "vo_empress_139501_003", "", 1, "幻境竜后の力…これほどまでに\n強力無比だとは…で、ですが…\n何があろうとわたくしは兄様を\nお守りします…命に代えても、必ず", 2, 139503, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (400, 125801, "リリ", "", "vo_empress_139501_004", 5, "vo_empress_139501_004", "", 1, "兄様への想いと、重ねてきた大切な\n時間が、たくさんの勇気と限界を\n超える奇跡をくれました。全ての人\nを救うため、参りましょう兄様…！", 3, 139502, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (401, 0, "クリア", "", "vo_empress_139601_001", 5, "vo_empress_139601_001", "", 1, "お兄さん、もし怪我しちゃっても\nすぐに治癒しますからご安心を！\nわたし決めましたから…もう二度と\n自分自身から逃げないって…！", 1, 139603, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (402, 0, "クリア", 10000, "vo_empress_139601_002", 3, "vo_empress_139601_002", 1, 1, "…アルシャトさん…\n謝ったって許してあげませんよ？\nあなたの前では、わたしちょっと\nいい子じゃいられませんから…っ！", 4002, 139603, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (403, 0, "クリア", "", "vo_empress_139601_003", 5, "vo_empress_139601_003", "", 1, "うぅっ…これが本気の幻境竜后…！\n…こんなの勝てっこありませんよ…\n…せめてお兄さんだけでも…なんて\n最後まで…諦めませんからっ…！", 2, 139603, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (404, 126001, "クリア", "", "vo_empress_139601_004", 5, "vo_empress_139601_004", "", 1, "お兄さんの気持ちが胸に溢れて…\nあ、えへへ…なんだか視界が\n滲んできちゃいました…♪\nわたしはもう、負けませんよ…っ！", 3, 139601, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (405, 0, "プレシア", "", "vo_empress_139701_001", 5, "vo_empress_139701_001", "", 1, "てき、いっぱい、しかも、つよすぎ\nけど、まけないよ\nお兄のほっぺ、たべて\nふるぱわー", 1, 139701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (406, 0, "プレシア", "", "vo_empress_139701_002", 5, "vo_empress_139701_002", "", 1, "ん\nまだまだ、いける\nお兄、パパ、なかま、いる\nむしゃぶるい", 1, 139701, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (407, 0, "プレシア", "", "vo_empress_139701_003", 5, "vo_empress_139701_003", "", 1, "しょうり、みえない\nせいぎ、まもれない\nそんなの、いや\nあきらめないよ、さいごまで", 2, 139703, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (408, 126101, "プレシア", "", "vo_empress_139701_004", 5, "vo_empress_139701_004", "", 1, "て、つなぐ\nせいめいりょく、たかまる\nぜったいしょうり！", 3, 139702, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (409, 140301, "ティア", "", "vo_empress_140301_004", 5, "vo_empress_140301_004", "", 1, "七冠、幻境竜后──LoAの開発者\nあんたにコワいコト教えてあげるわ\n些細なバグと思って放置したら\nゲームを壊すこともあるってね…♪", 3, 140301, 4);
